export const TASK_FILES: Record<string, Record<string, string>> = {"border_basis":{"border_basis/core/algorithm.py":"\"\"\"\r\nBorder basis algorithm (Algorithm 4.1 BBasis) from\r\n*Computational Algebra with Attention: Transformer Oracles for Border Basis Algorithms*\r\n(Kera, Pelleriti, Ishihara, Zimmer, Pokutta — arXiv:2505.23696, 2025).\r\n\r\nThis file is a verbatim port of\r\n`HiroshiKERA/OracleBorderBasis/src/border_basis_lib/border_basis.py`.\r\n\r\nLicense: see https://github.com/HiroshiKERA/OracleBorderBasis (MIT)\r\n\"\"\"\r\n\r\n# ruff: noqa\r\n# fmt: off\r\nfrom sage.all import *\r\nfrom typing import List, Tuple\r\nfrom pprint import pprint\r\nfrom time import time\r\n\r\n# for faster computation\r\nfrom sortedcontainers import SortedList\r\n\r\n\r\nclass BorderBasisCalculator:\r\n    def __init__(self, ring):\r\n        \"\"\"Initialize with a polynomial ring.\"\"\"\r\n        self.ring = ring\r\n        self.variables = ring.gens()\r\n\r\n        # sorting time\r\n        self.sorting_time = 0\r\n\r\n    def terms_up_to_degree(self, d: int) -> List:\r\n        \"\"\"Compute all terms up to degree d.\"\"\"\r\n        n = len(self.variables)\r\n        terms = [self.ring(1)]\r\n        for t in range(1, d + 1):\r\n            exponents = list(WeightedIntegerVectors(t, [1] * n))\r\n            terms.extend([self.ring.monomial(*e) for e in exponents])\r\n        return terms\r\n\r\n    def is_all_divisors_in(self, t, O: List) -> bool:\r\n        \"\"\"Check if adding term t to order ideal O maintains the order ideal property.\"\"\"\r\n        if t.degree() in (0, 1):\r\n            return True\r\n        return all([xi in O and t / xi in O for xi in self.variables if xi.divides(t)])\r\n\r\n    def border(self, O: List) -> List:\r\n        \"\"\"Compute the border of an order ideal O.\"\"\"\r\n        border = list()\r\n        for t in O:\r\n            for var in self.variables:\r\n                new_term = t * var\r\n                if new_term not in O and new_term not in border:\r\n                    border.append(new_term)\r\n        return border\r\n\r\n    def extend_V(self, V: List) -> List:\r\n        V_plus = []\r\n        for v in V:\r\n            for var in self.variables:\r\n                new_term = v * var\r\n                V_plus.append(new_term)\r\n        return V_plus\r\n\r\n    def compute_border_basis(self, F: List, weights: dict, use_fast_elimination=False, lstabilization_only=False) -> Tuple[List, List]:\r\n        \"\"\"Algorithm 4.1 (BBasis).\"\"\"\r\n        timings = {}\r\n\r\n        s = time()\r\n        d = max(f.degree() for f in F)\r\n        timings['step1_initial_degree'] = time() - s\r\n\r\n        while True:\r\n            s = time()\r\n            L = self.terms_up_to_degree(d)\r\n            M = self.compute_lstable_span(F, L, use_fast_elimination=use_fast_elimination)\r\n            timings['step2_lstable_span'] = time() - s\r\n\r\n            s = time()\r\n            terms_d = [t for t in L if t.degree() == d]\r\n            lt_M = set(f.lm() for f in M)\r\n            sufficient_universe = all(t in lt_M for t in terms_d)\r\n            timings['step3_check_universe'] = time() - s\r\n\r\n            if not sufficient_universe:\r\n                d += 1\r\n                continue\r\n\r\n            s = time()\r\n            d_old = d\r\n            d = len(self.terms_up_to_degree(d)) - len(M)\r\n            if d <= d_old:\r\n                M = [f for f in M if f.degree() <= d]\r\n            else:\r\n                M = self.compute_lstable_span(F, self.terms_up_to_degree(d), use_fast_elimination=use_fast_elimination)\r\n            timings['step4_adjust_dimension'] = time() - s\r\n            break\r\n\r\n        if not lstabilization_only:\r\n            s = time()\r\n            O = self.find_optimal_order_ideal(M, d, weights)\r\n            timings['step5_find_order_ideal'] = time() - s\r\n\r\n            s = time()\r\n            G = self.basis_transformation(M, O, use_fast_elimination=use_fast_elimination)\r\n            timings['step6_compute_basis'] = time() - s\r\n\r\n            timings['total_time'] = sum(timings.values())\r\n        else:\r\n            O = []\r\n            G = M\r\n\r\n        return G, O, timings\r\n\r\n    def basis_transformation(self, M: List, O: List, use_fast_elimination=False) -> List:\r\n        \"\"\"Algorithm 4.3 (BasisTransformation).\"\"\"\r\n        if not M:\r\n            return []\r\n\r\n        max_deg = max(p.degree() for p in M)\r\n\r\n        def term_key(p):\r\n            lt = p.lm()\r\n            return (lt not in O, lt)\r\n\r\n        M_sorted = sorted(M, key=term_key)\r\n        # gaussian_elimination returns (W, ...) — unpack the polynomial list.\r\n        Gprime = self.gaussian_elimination([], M_sorted, use_fast_elimination=use_fast_elimination)[0]\r\n\r\n        border = self.border(O)\r\n        G = [g for g in Gprime if g.lm() in border]\r\n\r\n        return G\r\n\r\n    def gaussian_elimination_fast(self, V: List, G: List) -> List:\r\n        \"\"\"Optimized Gaussian elimination using SortedList + binary search.\"\"\"\r\n        assert (all([v.lc() == 1 for v in V]))\r\n\r\n        reducers = SortedList(V, key=lambda p: p.lm())\r\n        W = []\r\n        non_zero_reductions_indices = []\r\n\r\n        from collections import defaultdict\r\n        reduction_indices = defaultdict(list)\r\n        reducer_indices = {}\r\n\r\n        for idx, f in enumerate(G):\r\n            if f == 0:\r\n                continue\r\n\r\n            reduced = True\r\n            while reduced and f != 0:\r\n                reduced = False\r\n                f_lead_term = f.lm()\r\n\r\n                index = reducers.bisect_key_left(f_lead_term)\r\n                if index < len(reducers) and reducers[index].lm() == f_lead_term:\r\n                    reducer = reducers[index]\r\n                    f = f - f.lc() * reducer\r\n                    reduced = True\r\n                    if index >= len(V):\r\n                        reduction_indices[idx].append(reducer_indices[index])\r\n\r\n            if f != 0:\r\n                f = f / f.lc()\r\n                reducers.add(f)\r\n                W.append(f)\r\n                non_zero_reductions_indices.append(idx)\r\n                reducer_indices[len(reducers) - 1] = idx\r\n                if not idx in reduction_indices.keys():\r\n                    reduction_indices[idx] = []\r\n\r\n        return W, non_zero_reductions_indices, reduction_indices\r\n\r\n    def gaussian_elimination(self, V: List, G: List, use_fast_elimination=False) -> List:\r\n        \"\"\"Algorithm 2.11 (GaussEl).\"\"\"\r\n        assert (all([v.lc() == 1 for v in V]))\r\n\r\n        if use_fast_elimination:\r\n            s = time()\r\n            V = sorted(V, key=lambda p: p.lm())\r\n            self.sorting_time += time() - s\r\n            return self.gaussian_elimination_fast(V, G)\r\n\r\n        reducers = list(V)\r\n        H = list(G)\r\n\r\n        while H:\r\n            f = H.pop(0)\r\n            if f == 0:\r\n                continue\r\n\r\n            reduced = True\r\n            while reduced and f != 0:\r\n                reduced = False\r\n                for reducer in reducers:\r\n                    if reducer.lm() == f.lm():\r\n                        f = f - f.lc() * reducer\r\n                        reduced = True\r\n                        break\r\n\r\n            if f != 0:\r\n                f = f / f.lc()\r\n                reducers.append(f)\r\n\r\n        W = reducers[len(V):]\r\n        return W, None\r\n\r\n    def compute_lstable_span(self, F: List, L: List, use_fast_elimination=False) -> List:\r\n        \"\"\"Algorithm 2.13 (LStabSpan).\"\"\"\r\n        d = max(l.degree() for l in L)\r\n        # gaussian_elimination returns (W, ...) — unpack the polynomial list.\r\n        V = self.gaussian_elimination([], F, use_fast_elimination=use_fast_elimination)[0]\r\n\r\n        while True:\r\n            W = self.gaussian_elimination(V, self.border(V), use_fast_elimination=use_fast_elimination)[0]\r\n            W = [w for w in W if w.degree() <= d]\r\n\r\n            if W:\r\n                V.extend(W)\r\n            else:\r\n                break\r\n\r\n        return V\r\n\r\n    def find_optimal_order_ideal(self, M: List, d: int, weights: dict) -> List:\r\n        \"\"\"Lemma 3.9: alternative description of order ideal polytope (MILP).\"\"\"\r\n        from scipy.optimize import milp, Bounds, LinearConstraint\r\n        from itertools import combinations\r\n        import numpy as np\r\n\r\n        terms = self.terms_up_to_degree(d - 1)\r\n        n_terms = len(terms)\r\n\r\n        c = np.array([-weights.get(term, 0) for term in terms])\r\n\r\n        integrality = np.ones(n_terms, dtype=np.int32)\r\n        bounds = Bounds(0, 1)\r\n\r\n        constraints = []\r\n\r\n        # Constraint (3.6a): Order ideal property\r\n        order_rows = []\r\n        for i, t1 in enumerate(terms):\r\n            for j, t2 in enumerate(terms):\r\n                if t1.divides(t2) and t1 != t2:\r\n                    row = np.zeros(n_terms)\r\n                    row[i] = -1\r\n                    row[j] = 1\r\n                    order_rows.append(row)\r\n\r\n        if order_rows:\r\n            A_order = np.vstack(order_rows)\r\n            constraints.append(LinearConstraint(A_order, -np.inf, 0))\r\n\r\n        # Constraint (3.6b): Size of order ideal is d\r\n        A_eq = np.ones((1, n_terms))\r\n        constraints.append(LinearConstraint(A_eq, d, d))\r\n\r\n        M_d_minus_1 = [f for f in M if f.degree() <= d - 1]\r\n        M_size = len(M_d_minus_1)\r\n\r\n        coeff_matrix = np.zeros((len(M_d_minus_1), len(terms)))\r\n        for i, f in enumerate(M_d_minus_1):\r\n            for j, term in enumerate(terms):\r\n                coeff = f.monomial_coefficient(term)\r\n                if coeff != 0:\r\n                    coeff_matrix[i, j] = float(coeff)\r\n\r\n        def get_submatrix_rank(U_indices):\r\n            return np.linalg.matrix_rank(coeff_matrix[:, U_indices])\r\n\r\n        # Constraint (3.6c)\r\n        rank_rows = []\r\n        rank_lbs = []\r\n\r\n        for U_indices in combinations(range(n_terms), M_size):\r\n            rank_U = get_submatrix_rank(U_indices)\r\n            row = np.zeros(n_terms)\r\n            row[list(U_indices)] = 1\r\n            rank_rows.append(row)\r\n            rank_lbs.append(M_size - rank_U)\r\n\r\n        if rank_rows:\r\n            A_rank = np.vstack(rank_rows)\r\n            constraints.append(LinearConstraint(A_rank, rank_lbs, np.inf))\r\n\r\n        options = {\r\n            'disp': False,\r\n            'presolve': True,\r\n            'mip_rel_gap': 1e-4,\r\n        }\r\n\r\n        result = milp(\r\n            c=c,\r\n            integrality=integrality,\r\n            bounds=bounds,\r\n            constraints=constraints,\r\n            options=options,\r\n        )\r\n\r\n        if not result.success:\r\n            raise ValueError(f\"MILP failed: {result.message}\")\r\n\r\n        O = list(set(term for i, term in enumerate(terms) if result.x[i] > 0.5))\r\n        O = sorted(O, key=lambda t: t)\r\n        return O\r\n","border_basis/core/formatter.py":"\"\"\"\r\nConvert SageMath polynomial objects to tokenizable strings for the border basis task.\r\n\r\nFormat\r\n------\r\nInput  : \"g1 | g2 | g3\"        (generators separated by ' | ')\r\nTarget : \"b1 | b2 | ... | bk\"  (border basis elements)\r\n\r\nExample\r\n-------\r\ngenerators:   g1 = x^2 + 6,  g2 = y^2 + x,  g3 = x*y + 1  (over GF(7))\r\nborder basis: B = [x + 1, y + 2, ...]\r\n→ input  = \"x^2 + 6 | y^2 + x | x*y + 1\"\r\n→ target = \"x + 1 | y + 2 | ...\"\r\n\"\"\"\r\n\r\nSEP = \" | \"\r\n\r\n\r\ndef poly_to_str(p) -> str:\r\n    \"\"\"Return the default SageMath string representation of a polynomial.\"\"\"\r\n    return str(p)\r\n\r\n\r\ndef format_input(generators: list) -> str:\r\n    \"\"\"\r\n    Concatenate all generators into a single input string.\r\n\r\n    Example: [g1, g2, g3] → \"g1 | g2 | g3\"\r\n    \"\"\"\r\n    return SEP.join(poly_to_str(g) for g in generators)\r\n\r\n\r\ndef format_target(basis: list) -> str:\r\n    \"\"\"\r\n    Concatenate all border basis elements into a single target string.\r\n\r\n    Example: [b1, b2, b3] → \"b1 | b2 | b3\"\r\n    \"\"\"\r\n    return SEP.join(poly_to_str(b) for b in basis)\r\n","border_basis/core/generator.py":"\"\"\"\r\nGenerate (problem, answer) pairs for the border basis task.\r\n\r\nMath\r\n----\r\nR = k[x, y]   (typically k = GF(p) for guaranteed 0-dimensional ideals)\r\nI = ⟨g1, g2, g3⟩ ⊂ R\r\n\r\nGiven F = [g1, g2, g3] sampled at random, the learning task is to predict\r\nthe **border basis** G of I (Algorithm 4.1 BBasis from the reference paper).\r\n\r\nReference\r\n---------\r\nImplements the data-generation pattern for the paper\r\n*Computational Algebra with Attention: Transformer Oracles for Border Basis\r\nAlgorithms* (Kera, Pelleriti, Ishihara, Zimmer, Pokutta — arXiv:2505.23696, 2025).\r\n\r\nThe underlying algorithm lives in `border_basis.core.algorithm.BorderBasisCalculator`,\r\nwhich is a verbatim port of\r\n`HiroshiKERA/OracleBorderBasis/src/border_basis_lib/border_basis.py`.\r\n\r\nClass-based generator pattern matches `issac2026_experiments/groebner/generate_dataset.py`.\r\n\"\"\"\r\n\r\nimport sage.all  # noqa: F401  # ensure Sage is initialised\r\nimport sage.misc.randstate as randstate  # type: ignore\r\n\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\nfrom .algorithm import BorderBasisCalculator\r\n\r\n\r\nclass BorderBasisGenerator:\r\n    \"\"\"\r\n    Problem generator: F = [g1, ..., g_{num_polynomials}],\r\n    answer G = border basis of ⟨F⟩.\r\n\r\n    Parameters\r\n    ----------\r\n    sampler : PolynomialSampler\r\n        Builds the random polynomials. Best used with a GF(p) field so that\r\n        the ideal is zero-dimensional with high probability.\r\n    num_polynomials : int\r\n        Number of generators (default 3).\r\n    use_fast_elimination : bool\r\n        If True, the Gaussian elimination step uses a sorted-list optimisation.\r\n    lstabilization_only : bool\r\n        If True, stop at the L-stable span (no order-ideal optimisation +\r\n        no basis transformation). Much faster, but you only get an intermediate\r\n        basis rather than the final border basis.\r\n    \"\"\"\r\n\r\n    def __init__(\r\n        self,\r\n        sampler: PolynomialSampler,\r\n        num_polynomials: int = 3,\r\n        use_fast_elimination: bool = True,\r\n        lstabilization_only: bool = False,\r\n    ):\r\n        self.sampler = sampler\r\n        self.num_polynomials = num_polynomials\r\n        self.use_fast_elimination = use_fast_elimination\r\n        self.lstabilization_only = lstabilization_only\r\n\r\n    def __call__(self, seed: int) -> tuple[list, list]:\r\n        randstate.set_random_seed(seed)\r\n        R = self.sampler.get_ring()\r\n        calculator = BorderBasisCalculator(R)\r\n\r\n        max_retries = 100\r\n        last_F, last_G = None, None\r\n        for _ in range(max_retries):\r\n            try:\r\n                F = self.sampler.sample(num_samples=self.num_polynomials)\r\n\r\n                # Border basis requires a 0-dimensional ideal.\r\n                ideal = R.ideal(F)\r\n                if ideal.dimension() != 0:\r\n                    continue\r\n\r\n                # Uniform weights over all terms up to max input degree.\r\n                d = max(f.degree() for f in F)\r\n                terms = calculator.terms_up_to_degree(d)\r\n                weights = {t: 1 for t in terms}\r\n\r\n                G, _O, _timings = calculator.compute_border_basis(\r\n                    F,\r\n                    weights,\r\n                    use_fast_elimination=self.use_fast_elimination,\r\n                    lstabilization_only=self.lstabilization_only,\r\n                )\r\n\r\n                last_F, last_G = list(F), list(G)\r\n                if last_G:\r\n                    return last_F, last_G\r\n            except Exception:\r\n                # MILP / Sage edge case — try next seed.\r\n                continue\r\n\r\n        return last_F, last_G\r\n","border_basis/core/metrics.py":"\"\"\"\r\nMetrics for the border basis task.\r\n\r\nsuccess_rate() is called after training to report evaluation accuracy.\r\nExact string match: the model wins only when its output is character-for-character\r\nidentical to the ground-truth border basis string.\r\n\"\"\"\r\n\r\n\r\ndef success_rate(predictions: list[str], targets: list[str]) -> float:\r\n    \"\"\"\r\n    Return the fraction of predictions that exactly match the target.\r\n\r\n    The ordering of border basis elements is deterministic (fixed by SageMath),\r\n    so exact string match is the correct metric.\r\n    \"\"\"\r\n    if not targets:\r\n        return 0.0\r\n    correct = sum(1 for p, t in zip(predictions, targets) if p.strip() == t.strip())\r\n    return correct / len(targets)\r\n","border_basis/core/parser.py":"\"\"\"\r\nLoad-time preprocessor for the border basis task.\r\n\r\nFor the default pipeline (text-based storage), no custom preprocessor is needed:\r\nCALT's text pipeline reads \"g1 | g2 | g3 # b1 | ... | bk\" directly.\r\n\r\nThis module is reserved for future extensions (e.g., alternative monomial orders).\r\n\"\"\"\r\n","border_basis/core/train.py":"\"\"\"\r\nTraining runner for the border basis task.\r\n\r\nOrchestrates the four CALT pipelines:\r\n  1. IOPipeline      — load text data, tokenize with UnifiedLexer\r\n  2. ModelPipeline   — build the Transformer\r\n  3. TrainerPipeline — train (HuggingFace Trainer under the hood)\r\n  4. evaluate_and_save_generation — decode predictions, compute success rate\r\n\r\nLexer format\r\n------------\r\nIf `data.lexer_config` points to a file with C/E expanded vocab, the pipeline\r\nautomatically wires `ExpandedFormLoadPreprocessor` to transform raw polynomial\r\nstrings into \"C1 E2 E0 + ...\" format before tokenization.\r\n\r\nUsage\r\n-----\r\n    from border_basis.core.train import run_training\r\n    from shared.config import load_config\r\n\r\n    cfg = load_config(\"configs/train.yaml\")\r\n    success_rate = run_training(cfg, data_cfg=load_config(\"configs/data.yaml\"))\r\n\"\"\"\r\n\r\nimport os\r\n\r\nimport sage.all  # noqa: F401  # initialise Sage before any submodule\r\nfrom omegaconf import DictConfig, OmegaConf\r\nfrom sage.all import GF, QQ, RR, ZZ, PolynomialRing  # type: ignore\r\n\r\nfrom shared.calt_adapter import (\r\n    ChainLoadPreprocessor,\r\n    ExpandedFormLoadPreprocessor,\r\n    IOPipeline,\r\n    ModelPipeline,\r\n    TextToSageLoadPreprocessor,\r\n    TrainerPipeline,\r\n    apply_dryrun_settings,\r\n    detect_lexer_format,\r\n)\r\n\r\n\r\ndef _build_source_ring(data_cfg: DictConfig):\r\n    \"\"\"Reconstruct the source PolynomialRing used at generation time.\"\"\"\r\n    sampler_cfg = dict(OmegaConf.to_container(data_cfg.sampler, resolve=True))\r\n    symbols = sampler_cfg.get(\"symbols\", \"x,y\")\r\n    field_str = sampler_cfg.get(\"field_str\", \"GF7\")\r\n    order = sampler_cfg.get(\"order\", \"degrevlex\")\r\n\r\n    if field_str == \"QQ\":\r\n        field = QQ\r\n    elif field_str == \"RR\":\r\n        field = RR\r\n    elif field_str == \"ZZ\":\r\n        field = ZZ\r\n    elif field_str.startswith(\"GF\"):\r\n        p = int(field_str[2:]) if field_str[2:].isdigit() else None\r\n        if not p:\r\n            raise ValueError(f\"Unsupported field_str for GF: {field_str!r}\")\r\n        field = GF(p)\r\n    else:\r\n        raise ValueError(f\"Unsupported field_str: {field_str!r}\")\r\n\r\n    names = [s.strip() for s in symbols.split(\",\")]\r\n    return PolynomialRing(field, names, order=order)\r\n\r\n\r\ndef build_load_preprocessor(cfg: DictConfig, data_cfg: DictConfig | None):\r\n    \"\"\"\r\n    Build the load-time preprocessor chain. Used by run_training AND the offline\r\n    preprocess.py so the two stay in sync.\r\n\r\n    For border_basis the only load preprocessor is ExpandedFormLoadPreprocessor\r\n    (when lexer_format == \"expanded\"). Otherwise None.\r\n\r\n    Returns\r\n    -------\r\n    tuple (preprocessor_or_None, format_str)\r\n    \"\"\"\r\n    lexer_format = detect_lexer_format(cfg.data.lexer_config)\r\n\r\n    chain = []\r\n    if lexer_format == \"expanded\":\r\n        if data_cfg is None:\r\n            raise ValueError(\"lexer format='expanded' requires data_cfg to rebuild the source ring.\")\r\n        R_src = _build_source_ring(data_cfg)\r\n        chain.append(TextToSageLoadPreprocessor(delimiter=\"|\", ring=R_src))\r\n        chain.append(ExpandedFormLoadPreprocessor(delimiter=\" | \"))\r\n\r\n    # Wire optional user post-processing hooks (task 3). See\r\n    # `shared/user_postprocessor.py` for details. Both slots are opt-in:\r\n    # if neither postprocessor file exists, this branch is a no-op.\r\n    from shared.user_postprocessor import (\r\n        get_user_postprocessors,\r\n        RawLineToTupleAdapter,\r\n        UserPostProcessorAdapter,\r\n    )\r\n    user_hooks = get_user_postprocessors(\"border_basis\")\r\n    if user_hooks:\r\n        if not chain:\r\n            chain.append(RawLineToTupleAdapter())\r\n        chain.append(UserPostProcessorAdapter(user_hooks))\r\n\r\n    if not chain:\r\n        return None, lexer_format\r\n    if len(chain) == 1:\r\n        return chain[0], lexer_format\r\n    return ChainLoadPreprocessor(*chain), lexer_format\r\n\r\n\r\ndef run_training(cfg: DictConfig, data_cfg: DictConfig | None = None, dryrun: bool = False) -> float:\r\n    \"\"\"\r\n    Run the full training pipeline for the border basis task.\r\n\r\n    Parameters\r\n    ----------\r\n    cfg : DictConfig\r\n        Loaded train.yaml.\r\n    data_cfg : DictConfig | None\r\n        Loaded data.yaml. Required when the lexer is in expanded format\r\n        (we need to rebuild the source ring to call TextToSageLoadPreprocessor).\r\n    dryrun : bool\r\n\r\n    Returns\r\n    -------\r\n    float : exact-match success rate on the test set.\r\n    \"\"\"\r\n    if dryrun:\r\n        apply_dryrun_settings(cfg)\r\n\r\n    save_dir = cfg.train.get(\"save_dir\", cfg.train.get(\"output_dir\", \"./results\"))\r\n    os.makedirs(save_dir, exist_ok=True)\r\n    OmegaConf.save(cfg, os.path.join(save_dir, \"train.yaml\"))\r\n\r\n    # Cache hierarchy: pretok > strings > raw. Mirrors groebner_basis/core/train.py.\r\n    # `training_order` is hard-coded \"border\" for border_basis (there is no FGLM\r\n    # variant) so we use that as the hash discriminator.\r\n    from calt.preprocess import (\r\n        maybe_use_pretokenized_cache,\r\n        maybe_use_processed_cache,\r\n    )\r\n    from shared.user_postprocessor import user_postprocessor_hash_contribution\r\n    hooks_hash = user_postprocessor_hash_contribution(\"border_basis\")\r\n\r\n    load_preprocessor, lexer_format = build_load_preprocessor(cfg, data_cfg)\r\n    training_order = \"border\"  # constant for this task\r\n\r\n    used_pretok = maybe_use_pretokenized_cache(cfg, data_cfg, training_order, lexer_format, extra_hash_bytes=hooks_hash)\r\n    if used_pretok:\r\n        print(f\"[run_training] using PRE-TOKENIZED cache (format={lexer_format})\")\r\n        io_pipeline = IOPipeline.from_config(cfg.data)\r\n    else:\r\n        used_strings = maybe_use_processed_cache(cfg, data_cfg, training_order, lexer_format, extra_hash_bytes=hooks_hash)\r\n        if used_strings:\r\n            print(f\"[run_training] using strings cache (format={lexer_format})\")\r\n            io_pipeline = IOPipeline.from_config(cfg.data)\r\n        else:\r\n            io_pipeline = IOPipeline.from_config(cfg.data)\r\n            if load_preprocessor is not None:\r\n                io_pipeline.dataset_load_preprocessor = load_preprocessor\r\n            print(f\"[run_training] no cache; lexer format={lexer_format}\")\r\n\r\n    io_dict = io_pipeline.build()\r\n    model = ModelPipeline.from_io_dict(cfg.model, io_dict).build()\r\n    trainer_pipeline = TrainerPipeline.from_io_dict(cfg.train, model, io_dict).build()\r\n\r\n    trainer_pipeline.train()\r\n    trainer_pipeline.save_model()\r\n    return trainer_pipeline.evaluate_and_save_generation()\r\n","border_basis/core/__init__.py":"from .generator import BorderBasisGenerator\r\nfrom .algorithm import BorderBasisCalculator\r\nfrom .formatter import format_input, format_target\r\nfrom .metrics import success_rate\r\nfrom .train import run_training\r\n\r\n__all__ = [\r\n    \"BorderBasisGenerator\",\r\n    \"BorderBasisCalculator\",\r\n    \"format_input\",\r\n    \"format_target\",\r\n    \"success_rate\",\r\n    \"run_training\",\r\n]\r\n","border_basis/experiments/ablation/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 3\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 3\r\n  num_decoder_heads: 4\r\n  d_model: 256\r\n  encoder_ffn_dim: 1024\r\n  decoder_ffn_dim: 1024\r\n  max_sequence_length: 512\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 100\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 32\r\n  test_batch_size: 32\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 4\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: border_basis_ablation\r\n    name: ablation\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../../toy/data/GF7/train_raw.txt\r\n  test_dataset_path: ../../toy/data/GF7/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","border_basis/experiments/ablation/README.md":"# Border basis — ablation experiment\r\n\r\n**Goal**: vary the model size and observe how performance changes on the toy\r\nborder-basis dataset (GF(7), 2 variables).\r\n\r\n| Knob | Choices |\r\n|------|---------|\r\n| `--model_size` | `small`, `medium`, `large` |\r\n\r\n## How to run\r\n```bash\r\ncd border_basis/experiments/ablation/scripts\r\npython train.py --model_size large\r\n```\r\n\r\nReuses the dataset generated by the toy experiment (`../../toy/data/GF7/`).\r\nOutputs land in `outputs/results_<model_size>/`.\r\n","border_basis/experiments/ablation/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","border_basis/experiments/ablation/scripts/train.py":"\"\"\"Ablation: vary model size for the border basis task.\r\n\r\nUsage: python train.py --model_size {small,medium,large}\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom border_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\nMODEL_SIZES = {\r\n    \"small\":  dict(d_model=128, num_encoder_layers=2, num_decoder_layers=2,\r\n                   encoder_ffn_dim=512, decoder_ffn_dim=512,\r\n                   num_encoder_heads=4, num_decoder_heads=4),\r\n    \"medium\": dict(d_model=256, num_encoder_layers=4, num_decoder_layers=4,\r\n                   encoder_ffn_dim=1024, decoder_ffn_dim=1024,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n    \"large\":  dict(d_model=512, num_encoder_layers=6, num_decoder_layers=6,\r\n                   encoder_ffn_dim=2048, decoder_ffn_dim=2048,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n}\r\n\r\n\r\n@click.command()\r\n@click.option(\"--model_size\", type=click.Choice(list(MODEL_SIZES)), default=\"medium\")\r\n@click.option(\"--dryrun\", is_flag=True)\r\ndef main(model_size: str, dryrun: bool) -> None:\r\n    cfg = OmegaConf.load(config_dir(__file__) / \"train.yaml\")\r\n    cfg.model = OmegaConf.create({**OmegaConf.to_container(cfg.model), **MODEL_SIZES[model_size]})\r\n    cfg.train.save_dir = f\"../outputs/results_{model_size}\"\r\n    cfg.train.wandb.name = f\"ablation_{model_size}\"\r\n\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, dryrun=dryrun)\r\n    print(f\"[{model_size}] Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/experiments/finite_field/configs/data.yaml":"# Border basis finite_field: generate.py overrides field_str via --p flag.\r\n\r\nsampler:\r\n  symbols: \"x,y\"\r\n  field_str: \"GF7\"        # overridden by generate.py --p\r\n  order: \"degrevlex\"\r\n  max_num_terms: 4\r\n  max_degree: 3\r\n  min_degree: 1\r\n  max_coeff: 0\r\n  degree_sampling: \"uniform\"\r\n  term_sampling: \"uniform\"\r\n\r\nproblem_generator:\r\n  num_polynomials: 3\r\n\r\ndataset:\r\n  save_dir: \"../data/GF7\" # overridden by generate.py --p\r\n  num_train_samples: 5000\r\n  num_test_samples: 500\r\n  batch_size: 500\r\n  n_jobs: 8\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sagemath\"\r\n  save_text: true\r\n  save_json: false\r\n","border_basis/experiments/finite_field/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 3\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 3\r\n  num_decoder_heads: 4\r\n  d_model: 256\r\n  encoder_ffn_dim: 1024\r\n  decoder_ffn_dim: 1024\r\n  max_sequence_length: 512\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 50\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 16\r\n  test_batch_size: 16\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 2\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: border_basis\r\n    name: finite_field_GF7\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/GF7/train_raw.txt\r\n  test_dataset_path: ../data/GF7/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","border_basis/experiments/finite_field/README.md":"# Border basis — finite_field experiment\r\n\r\n**Goal**: vary the size of the base finite field GF(p) and observe how the border\r\nbasis structure changes with p.\r\n\r\n`p ∈ {2, 5, 7, 11}` is selectable via CLI flag.\r\n\r\n## How to run\r\n```bash\r\ncd border_basis/experiments/finite_field/scripts\r\npython generate.py --p 5         # → ../data/GF5/\r\npython train.py --p 5\r\n```\r\n\r\nEach `p` writes its dataset to `../data/GF{p}/` and the trained model to\r\n`../outputs/results_GF{p}/`, so runs do not clash.\r\n","border_basis/experiments/finite_field/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","border_basis/experiments/finite_field/scripts/generate.py":"\"\"\"Generate border basis data over GF(p), p selectable via --p.\r\n\r\nUsage: python generate.py --p 5\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\nfrom border_basis.core.generator import BorderBasisGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\"--p\", type=int, default=None, help=\"Prime for GF(p).\")\r\n@click.option(\"--config_path\", type=click.Path(exists=True), default=None)\r\ndef main(p: int | None, config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n\r\n    if p is not None:\r\n        cfg.sampler.field_str = f\"GF{p}\"\r\n        cfg.dataset.save_dir = f\"../data/GF{p}\"\r\n\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    sampler_cfg = dict(OmegaConf.to_container(cfg.sampler, resolve=True))\r\n    sampler = PolynomialSampler(**sampler_cfg)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = BorderBasisGenerator(sampler=sampler, **gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(f\"Dataset generation completed (GF{p or cfg.sampler.field_str[2:]})\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/experiments/finite_field/scripts/train.py":"\"\"\"Train border basis model over GF(p).\r\n\r\nUsage: python train.py --p 5\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom border_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\"--p\", type=int, default=None, help=\"Prime for GF(p).\")\r\n@click.option(\"--config_path\", type=click.Path(exists=True), default=None)\r\n@click.option(\"--dryrun\", is_flag=True)\r\ndef main(p: int | None, config_path: str | None, dryrun: bool) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n\r\n    if p is not None:\r\n        cfg.data.train_dataset_path = f\"../data/GF{p}/train_raw.txt\"\r\n        cfg.data.test_dataset_path = f\"../data/GF{p}/test_raw.txt\"\r\n        cfg.train.save_dir = f\"../outputs/results_GF{p}\"\r\n        if hasattr(cfg.train, \"wandb\") and hasattr(cfg.train.wandb, \"name\"):\r\n            cfg.train.wandb.name = f\"finite_field_GF{p}\"\r\n\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, dryrun=dryrun)\r\n    print(f\"Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/experiments/toy/configs/data.yaml":"# Border basis task (toy): G=[g1,g2,g3] over GF(7)[x,y] -> border basis of (G)\r\n\r\nsampler:\r\n  symbols: \"x,y\"\r\n  field_str: \"GF7\"\r\n  order: \"degrevlex\"\r\n  max_num_terms: 4\r\n  max_degree: 3\r\n  min_degree: 1\r\n  max_coeff: 0\r\n  degree_sampling: \"uniform\"\r\n  term_sampling: \"uniform\"\r\n\r\nproblem_generator:\r\n  num_polynomials: 3\r\n\r\ndataset:\r\n  save_dir: \"../data/GF7\"\r\n  num_train_samples: 1000\r\n  num_test_samples: 200\r\n  batch_size: 100\r\n  n_jobs: 4\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sagemath\"\r\n  save_text: true\r\n  save_json: false\r\n","border_basis/experiments/toy/configs/lexer.yaml":"vocab:\r\n  range:\r\n    numbers: [\"\", -10, 10]  # GF(7) coefficients are 0-6\r\n  misc: [\"+\", \"-\", \"*\", \"^\", \"x\", \"y\", \"|\"]\r\n  special_tokens: {}\r\n  flags:\r\n    include_base_vocab: true\r\n    include_base_special_tokens: true\r\n\r\nnumber_policy:\r\n  attach_sign: true\r\n  digit_group: 1\r\n  allow_float: false\r\n\r\nstrict: true\r\ninclude_base_vocab: true\r\n","border_basis/experiments/toy/configs/lexer_expanded.yaml":"# Lexer EXPANDED — C/E form for the border basis task (GF(p)[x, y]).\r\n#\r\n# Same C/E scheme as groebner, but the coefficient range is narrower\r\n# (modular arithmetic in GF(7) gives coefficients in 0..6).\r\n#\r\n# Example: \"2*x*y + 5*y + 1\" → \"C2 E1 E1 + C5 E0 E1 + C1 E0 E0\"\r\n#\r\n# Reference: ISSAC '26 paper §2.2.\r\n\r\nvocab:\r\n  range:\r\n    coefficients: [\"C\", 0, 6]     # GF(7): coefficients are 0..6\r\n    exponents:    [\"E\", 0, 5]     # max_degree=3 + safety margin\r\n  misc: [\"+\", \"|\"]\r\n  special_tokens: {}\r\n  flags:\r\n    include_base_vocab: true\r\n    include_base_special_tokens: true\r\n\r\nnumber_policy:\r\n  attach_sign: true\r\n  digit_group: 0\r\n  allow_float: false\r\n\r\nstrict: true\r\ninclude_base_vocab: true\r\n","border_basis/experiments/toy/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 3\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 3\r\n  num_decoder_heads: 4\r\n  d_model: 256\r\n  encoder_ffn_dim: 1024\r\n  decoder_ffn_dim: 1024\r\n  max_sequence_length: 512\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 50\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 16\r\n  test_batch_size: 16\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 2\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: border_basis\r\n    name: toy_gf7\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/GF7/train_raw.txt\r\n  test_dataset_path: ../data/GF7/test_raw.txt\r\n  lexer_config: ../configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","border_basis/experiments/toy/scripts/evaluate.py":"\"\"\"Print evaluation results for the border basis toy experiment.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    show_examples(generated, references, n=5, successes=False)\r\n","border_basis/experiments/toy/scripts/generate.py":"\"\"\"Generate the border basis dataset for the toy experiment.\r\n\r\nReference: issac2026_experiments/groebner/generate_dataset.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\nfrom border_basis.core.generator import BorderBasisGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml).\",\r\n)\r\ndef main(config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    sampler_cfg = dict(OmegaConf.to_container(cfg.sampler, resolve=True))\r\n    sampler = PolynomialSampler(**sampler_cfg)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = BorderBasisGenerator(sampler=sampler, **gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(\"Dataset generation completed\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/experiments/toy/scripts/preprocess.py":"\"\"\"Materialize a preprocessing cache for the toy border basis experiment.\r\n\r\nMirrors groebner_basis/experiments/toy/scripts/preprocess.py — see that file\r\nfor the rationale. By default builds a *pre-tokenized* cache so that training\r\nperforms zero tokenization at runtime.\r\n\r\nUsage\r\n-----\r\n    cd border_basis/experiments/toy/scripts\r\n    python preprocess.py                     # pretokenized cache (default)\r\n    python preprocess.py --no-pretokenize    # strings cache (skip SageMath only)\r\n    python preprocess.py --force             # rebuild even if hash matches\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom border_basis.core.train import build_load_preprocessor\r\nfrom calt.preprocess import preprocess_to_ids, run_preprocess\r\nfrom shared.paths import config_dir\r\nfrom shared.user_postprocessor import user_postprocessor_hash_contribution\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML (defaults to ../configs/train.yaml).\",\r\n)\r\n@click.option(\r\n    \"--data_config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml).\",\r\n)\r\n@click.option(\"--force\", is_flag=True, help=\"Rebuild even if hash matches.\")\r\n@click.option(\r\n    \"--pretokenize/--no-pretokenize\",\r\n    default=True,\r\n    help=\"Pre-tokenize all the way to input_ids (default ON).\",\r\n)\r\ndef main(\r\n    config_path: str | None,\r\n    data_config_path: str | None,\r\n    force: bool,\r\n    pretokenize: bool,\r\n) -> None:\r\n    \"\"\"Preprocess raw .txt → JSONL cache for fast training startup.\"\"\"\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n\r\n    data_path = Path(data_config_path) if data_config_path else config_dir(__file__) / \"data.yaml\"\r\n    data_cfg = OmegaConf.load(data_path) if data_path.exists() else None\r\n\r\n    load_preprocessor, lexer_format = build_load_preprocessor(cfg, data_cfg)\r\n    training_order = \"border\"  # constant for this task\r\n    hooks_hash = user_postprocessor_hash_contribution(\"border_basis\")\r\n\r\n    if pretokenize:\r\n        cache_dir = preprocess_to_ids(\r\n            cfg, data_cfg, training_order, lexer_format, load_preprocessor,\r\n            force=force, extra_hash_bytes=hooks_hash,\r\n        )\r\n    else:\r\n        cache_dir = run_preprocess(\r\n            cfg, data_cfg, training_order, lexer_format, load_preprocessor,\r\n            force=force, extra_hash_bytes=hooks_hash,\r\n        )\r\n    print(f\"[done] cache at: {cache_dir}\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/experiments/toy/scripts/run.sh":"#!/bin/bash\r\nset -e\r\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\r\ncd \"$SCRIPT_DIR\"\r\n\r\necho \"=== Step 1/3: Generate data ===\"\r\npython generate.py\r\n\r\necho \"=== Step 2/3: Train ===\"\r\npython train.py \"$@\"\r\n\r\necho \"=== Step 3/3: Evaluate ===\"\r\npython evaluate.py\r\n","border_basis/experiments/toy/scripts/train.py":"\"\"\"Train the border basis model for the toy experiment.\r\n\r\nIf the lexer.yaml referenced in train.yaml is in C/E expanded format, the\r\ndata_config (--data_config_path) is required to rebuild the source ring.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom border_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML (defaults to ../configs/train.yaml).\",\r\n)\r\n@click.option(\r\n    \"--data_config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML. Required if lexer is in expanded format.\",\r\n)\r\n@click.option(\"--dryrun\", is_flag=True, help=\"Reduced settings for a fast smoke test.\")\r\ndef main(config_path: str | None, data_config_path: str | None, dryrun: bool) -> None:\r\n    \"\"\"Train a Transformer to compute border bases from polynomial generators.\"\"\"\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.train.seed)\r\n\r\n    data_cfg = None\r\n    data_path = Path(data_config_path) if data_config_path else config_dir(__file__) / \"data.yaml\"\r\n    if data_path.exists():\r\n        data_cfg = OmegaConf.load(data_path)\r\n\r\n    success = run_training(cfg, data_cfg=data_cfg, dryrun=dryrun)\r\n    print(f\"Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","border_basis/README.md":"# border_basis\r\n\r\n**Task**: Given polynomial generators of a zero-dimensional ideal I ⊂ K[x, y, z],\r\npredict the border basis of I.\r\n\r\n## The math\r\n\r\n### What is a border basis?\r\n\r\nLet I ⊂ K[x1,…,xn] be a **zero-dimensional ideal** (the variety V(I) is a finite set\r\nof points). A **border basis** of I is an alternative to a Gröbner basis that is:\r\n\r\n- Uniquely determined by a chosen **order ideal** O(B) (a set of monomials\r\n  closed under divisibility that indexes the quotient ring K[x]/I)\r\n- Often **more numerically stable** than a Gröbner basis\r\n- Related to the **BM algorithm** (Mourrain / Cerlienco–Mureddu)\r\n\r\n**Formal definition**:\r\nLet O = {t1, …, tμ} be an order ideal for I of size μ = dimK(K[x]/I).\r\nThe **border** ∂O = {x·ti : ti ∈ O, x·ti ∉ O} of O consists of the monomials\r\njust outside O. The border basis B = {b_τ : τ ∈ ∂O} satisfies:\r\n\r\n    b_τ = τ − Σ_{ti ∈ O} c_{τ,i} · ti\r\n\r\ni.e., each border monomial τ reduces to a linear combination of O-monomials.\r\n\r\n### Key difference from Gröbner basis\r\n\r\n| | Gröbner basis | Border basis |\r\n|---|---|---|\r\n| Ideal type | Any ideal | Zero-dimensional ideals |\r\n| Monomial order | Required (lex, grevlex, …) | Not required |\r\n| Numerical stability | Often poor | Often better |\r\n| Uniqueness | Up to choice of order | Up to choice of order ideal |\r\n\r\n### This task\r\n\r\n- **Input**: polynomial generators g1, …, gk over GF(p) (a finite field)\r\n- **Output**: the elements of the border basis of ⟨g1,…,gk⟩\r\n\r\nWorking over GF(p) ensures the ideal is automatically zero-dimensional\r\n(the variety V(I) ⊆ GF(p)^n is a finite set of at most p^n points).\r\n\r\n## Status\r\n\r\n✅ **Real border basis algorithm implemented** in `core/algorithm.py`. It is a\r\nverbatim port of Algorithm 4.1 (BBasis) from:\r\n\r\n> Kera, Pelleriti, Ishihara, Zimmer, Pokutta,\r\n> *Computational Algebra with Attention: Transformer Oracles for Border Basis Algorithms*,\r\n> arXiv:2505.23696, 2025.\r\n> Code: <https://github.com/HiroshiKERA/OracleBorderBasis>\r\n\r\nThe algorithm:\r\n1. Computes the **L-stable span** of F up to a sufficient degree (Algorithm 2.13).\r\n2. Finds the **optimal order ideal** O via a Mixed Integer Linear Program\r\n   (Lemma 3.9, solved with `scipy.optimize.milp`).\r\n3. Applies a **basis transformation** (Algorithm 4.3) to extract the border basis G.\r\n\r\nFast Gaussian elimination uses a `SortedList` from `sortedcontainers` for\r\nO(log n) reducer lookup.\r\n\r\n## Experiments\r\n\r\n| Experiment | What varies |\r\n|---|---|\r\n| `toy/` | Small field GF(7), 2 variables, small degree |\r\n| `finite_field/` | Compare GF(7), GF(11), GF(17), GF(31) |\r\n| `ablation/` | Number of generators, degree bounds |\r\n\r\n## Quick start (once TODO is filled)\r\n\r\n```bash\r\ncd border_basis/experiments/toy/scripts\r\npython generate.py\r\npython train.py\r\npython evaluate.py\r\n```\r\n\r\n## User post-processing hooks (optional)\r\n\r\nTwo opt-in slots inject custom `(input, target)` transformations between the\r\nload chain and tokenization. Identical mechanism to `groebner_basis`, see\r\n[groebner_basis/README.md](../groebner_basis/README.md#user-post-processing-hooks-optional).\r\n\r\nPer-task slot for this task: `border_basis/core/postprocessor.py` (copy the\r\n`.example` file and edit).\r\n\r\n## Tokenization format (raw vs C/E expanded)\r\n\r\nSame mechanism as `groebner_basis`. Two lexer configs are provided and the format is\r\nauto-detected from `data.lexer_config` in your `train.yaml`:\r\n\r\n```yaml\r\ndata:\r\n  lexer_config: ../configs/lexer.yaml           # raw  (default, ISSAC '26 paper)\r\n  # lexer_config: ../configs/lexer_expanded.yaml  # C/E expanded (smaller vocab)\r\n```\r\n\r\n- **raw** — `\"x^2 + y\"` → `[\"x\", \"^\", \"2\", \"+\", \"y\"]`. Default.\r\n- **expanded** — each term as `C<coef> E<exp_x> E<exp_y>`. Fixed-size vocab.\r\n\r\nWhen `expanded` is detected, `core/train.py` wires `ExpandedFormLoadPreprocessor` into\r\nthe load chain and **requires** `--data_config_path` (it needs the source ring from\r\n`data.yaml`). See [groebner_basis/README.md](../groebner_basis/README.md#tokenization-format-raw-vs-ce-expanded)\r\nfor details and trade-offs (they are identical for both tasks).\r\n"},"groebner_basis":{"groebner_basis/core/formatter.py":"\"\"\"\r\nHelper functions to render SageMath polynomial objects as text strings.\r\n\r\nFormat\r\n------\r\nInput  : \"f1 | f2\"             (generators separated by ' | ')\r\nTarget : \"g1 | g2 | ... | gk\"  (Gröbner basis elements)\r\n\r\nThese are NOT used by the CALT DatasetPipeline (which calls str() on each\r\npolynomial automatically and joins lists with ' | '). They exist for:\r\n  - inspecting generated samples in notebooks/REPL\r\n  - building unit tests\r\n\"\"\"\r\n\r\nSEP = \" | \"\r\n\r\n\r\ndef format_input(generators: list) -> str:\r\n    \"\"\"[f1, f2] → 'f1 | f2'\"\"\"\r\n    return SEP.join(str(g) for g in generators)\r\n\r\n\r\ndef format_target(basis: list) -> str:\r\n    \"\"\"[g1, ..., gk] → 'g1 | ... | gk'\"\"\"\r\n    return SEP.join(str(g) for g in basis)\r\n","groebner_basis/core/generator.py":"\"\"\"\r\nGenerate (problem, answer) pairs for the Gröbner basis computation task.\r\n\r\nMath\r\n----\r\nR = k[x, y],  k ∈ {QQ, GF(7), ZZ}\r\nI = ⟨f1, f2⟩  (ideal generated by two polynomials)\r\n\r\nGiven f1, f2 ∈ R sampled at random:\r\n  - G = degrevlex Gröbner basis of I  (Buchberger's algorithm via SageMath)\r\n\r\nThe learning task is: given (f1, f2), predict G.\r\n\r\nReference\r\n---------\r\nMirrors `issac2026_experiments/groebner/generate_dataset.py` from the\r\nHiroshiKERA/calt branch experiment/issac2026.\r\n\"\"\"\r\n\r\nimport sage.all  # noqa: F401  # ensure Sage is initialised before any submodule import\r\nimport sage.misc.randstate as randstate  # type: ignore\r\nfrom sage.rings.rational_field import QQ  # type: ignore\r\n\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\n\r\ndef _has_large_rational_coefficients(polynomials, threshold: int = 100) -> bool:\r\n    \"\"\"\r\n    Return True if any polynomial has a rational coefficient whose numerator OR\r\n    denominator has |value| ≥ threshold.\r\n\r\n    Used to reject samples with Buchberger coefficient swell over QQ.\r\n    For non-QQ fields (GF(p), ZZ) this check is silently skipped per coefficient.\r\n    \"\"\"\r\n    for p in polynomials:\r\n        for c in p.coefficients():\r\n            try:\r\n                num = c.numerator()\r\n                den = c.denominator()\r\n            except Exception:\r\n                continue\r\n            if abs(int(num)) >= threshold or abs(int(den)) >= threshold:\r\n                return True\r\n    return False\r\n\r\n\r\nclass GroebnerGenerator:\r\n    \"\"\"\r\n    Problem generator: F = [f1, ..., f_{num_polynomials}], answer = Gröbner basis of ⟨F⟩.\r\n\r\n    Returns SageMath polynomial objects; the CALT DatasetPipeline converts them\r\n    to strings via str() and joins with ' | '.\r\n\r\n    Parameters\r\n    ----------\r\n    sampler : PolynomialSampler\r\n        Builds the random polynomials in the chosen ring.\r\n    num_polynomials : int\r\n        Number of generators (default 2).\r\n    \"\"\"\r\n\r\n    def __init__(self, sampler: PolynomialSampler, num_polynomials: int = 2):\r\n        self.sampler = sampler\r\n        self.num_polynomials = num_polynomials\r\n\r\n    def __call__(self, seed: int) -> tuple[list, list]:\r\n        randstate.set_random_seed(seed)\r\n\r\n        R = self.sampler.get_ring()\r\n        is_QQ = R.base_ring() == QQ\r\n\r\n        # For QQ only: reject samples with rational coefficients ≥ 3 digits in numerator or denominator\r\n        max_retries = 100\r\n        last_F, last_G = None, None\r\n        for _ in range(max_retries):\r\n            F = self.sampler.sample(num_samples=self.num_polynomials)\r\n            ideal = R.ideal(F)\r\n            G = list(ideal.groebner_basis())\r\n            last_F, last_G = F, G\r\n\r\n            if not is_QQ:\r\n                break\r\n            if not _has_large_rational_coefficients(list(F) + list(G), threshold=100):\r\n                break\r\n\r\n        return last_F, last_G\r\n","groebner_basis/core/metrics.py":"\"\"\"\r\nMetrics for the Gröbner basis computation task.\r\n\r\nsuccess_rate() is called after training to report evaluation accuracy.\r\nExact string match: the model wins only when its output is character-for-character\r\nidentical to the ground-truth Gröbner basis string.\r\n\"\"\"\r\n\r\n\r\ndef success_rate(predictions: list[str], targets: list[str]) -> float:\r\n    \"\"\"\r\n    Return the fraction of predictions that exactly match the target.\r\n\r\n    Exact string match (after stripping whitespace) is the standard metric\r\n    for this task — any difference in coefficients or ordering counts as failure.\r\n    \"\"\"\r\n    if not targets:\r\n        return 0.0\r\n    correct = sum(1 for p, t in zip(predictions, targets) if p.strip() == t.strip())\r\n    return correct / len(targets)\r\n","groebner_basis/core/parser.py":"\"\"\"\r\nLoad-time preprocessor for lex order training of the Gröbner basis task.\r\n\r\nFor the default pipeline (degrevlex), no custom preprocessor is needed:\r\nCALT's text pipeline reads \"f1 | f2 # g1 | ... | gk\" directly.\r\n\r\nFor lex order training, the train.py wires up a ChainLoadPreprocessor:\r\n    TextToSageLoadPreprocessor  →  GroebnerLexOrderPreprocessor\r\n\r\nThe first stage parses text into SageMath polynomials in the (degrevlex) source ring.\r\nThe second stage converts F to a lex ring and recomputes the lex Gröbner basis.\r\n\r\nReference\r\n---------\r\nMirrors `_GroebnerLexOrderPreprocessor` from\r\nissac2026_experiments/groebner/train.py in HiroshiKERA/calt@experiment/issac2026.\r\n\"\"\"\r\n\r\nfrom typing import Any\r\n\r\nimport sage.all  # noqa: F401  # ensure Sage is initialised\r\nfrom sage.all import PolynomialRing  # type: ignore\r\n\r\n\r\nclass GroebnerLexOrderPreprocessor:\r\n    \"\"\"\r\n    Load-time converter: dict {'problem': [f1,f2,...], 'solution': [...]} →\r\n    (input_text, target_text) in lex order.\r\n\r\n    F and the lex Gröbner basis are joined with ' | '.\r\n    Requires a zero-dimensional ideal for the Gröbner basis to terminate.\r\n\r\n    Parameters\r\n    ----------\r\n    ring_src : PolynomialRing\r\n        The source ring used for generation (typically degrevlex).\r\n    delimiter : str\r\n        Separator character (default '|').\r\n    \"\"\"\r\n\r\n    def __init__(self, ring_src, delimiter: str = \"|\"):\r\n        self.R_src = ring_src\r\n        base = ring_src.base_ring()\r\n        names = ring_src.variable_names()\r\n        self.R_lex = PolynomialRing(base, names, order=\"lex\")\r\n        self.delimiter = delimiter\r\n\r\n    def process_sample(self, source: dict[str, Any]) -> tuple[str, str]:\r\n        if not isinstance(source, dict):\r\n            raise TypeError(\r\n                f\"GroebnerLexOrderPreprocessor expects dict source, got {type(source).__name__}\"\r\n            )\r\n        F_src = source.get(\"problem\") or []\r\n        F_lex = [self.R_lex(f) for f in F_src]\r\n        I_lex = self.R_lex.ideal(F_lex)\r\n        # Force `libsingular:std` instead of the default. The default tries\r\n        # `stdhilb`, which raises `intvec`/`bigintvec` on some QQ-lex inputs in\r\n        # SageMath 10.6. `libsingular:std` is the standard, stable choice for\r\n        # both QQ and GF(p).\r\n        G_lex = list(I_lex.groebner_basis(\"libsingular:std\"))\r\n\r\n        sep = f\" {self.delimiter} \"\r\n        input_text = sep.join(str(f) for f in F_lex)\r\n        target_text = sep.join(str(g) for g in G_lex)\r\n        return input_text, target_text\r\n","groebner_basis/core/train.py":"\"\"\"\r\nTraining runner for the Gröbner basis computation task.\r\n\r\nOrchestrates the four CALT pipelines:\r\n  1. IOPipeline      — load text data, tokenize with UnifiedLexer\r\n  2. ModelPipeline   — build the Transformer\r\n  3. TrainerPipeline — train (HuggingFace Trainer under the hood)\r\n  4. evaluate_and_save_generation — decode predictions, compute success rate\r\n\r\nFor `training_order=\"lex\"`, a ChainLoadPreprocessor (TextToSage → GroebnerLexOrder)\r\nis wired into the IOPipeline; it rebuilds F over a lex ring and recomputes\r\nthe Gröbner basis at load time.\r\n\r\nReference\r\n---------\r\nMirrors `issac2026_experiments/groebner/train.py` (HiroshiKERA/calt@experiment/issac2026).\r\n\"\"\"\r\n\r\nimport os\r\n\r\nimport sage.all  # noqa: F401  # initialise Sage before any submodule\r\nfrom omegaconf import DictConfig, OmegaConf\r\nfrom sage.all import GF, QQ, RR, ZZ, PolynomialRing  # type: ignore\r\n\r\nfrom calt.io import (\r\n    ChainLoadPreprocessor,\r\n    ExpandedFormLoadPreprocessor,\r\n    IOPipeline,\r\n    TextToSageLoadPreprocessor,\r\n)\r\nfrom calt.models import ModelPipeline\r\nfrom calt.trainer import TrainerPipeline, apply_dryrun_settings\r\n\r\nfrom shared.calt_adapter import detect_lexer_format\r\n\r\nfrom .parser import GroebnerLexOrderPreprocessor\r\n\r\n\r\ndef _build_source_ring(data_cfg: DictConfig):\r\n    \"\"\"Reconstruct the source PolynomialRing used at generation time.\"\"\"\r\n    sampler_cfg = dict(OmegaConf.to_container(data_cfg.sampler, resolve=True))\r\n    symbols = sampler_cfg.get(\"symbols\", \"x,y\")\r\n    field_str = sampler_cfg.get(\"field_str\", \"QQ\")\r\n    order = sampler_cfg.get(\"order\", \"degrevlex\")\r\n\r\n    if field_str == \"QQ\":\r\n        field = QQ\r\n    elif field_str == \"RR\":\r\n        field = RR\r\n    elif field_str == \"ZZ\":\r\n        field = ZZ\r\n    elif field_str.startswith(\"GF\"):\r\n        p = int(field_str[2:]) if field_str[2:].isdigit() else None\r\n        if not p:\r\n            raise ValueError(f\"Unsupported field_str for GF: {field_str!r}\")\r\n        field = GF(p)\r\n    else:\r\n        raise ValueError(f\"Unsupported field_str: {field_str!r}\")\r\n\r\n    names = [s.strip() for s in symbols.split(\",\")]\r\n    return PolynomialRing(field, names, order=order)\r\n\r\n\r\ndef build_load_preprocessor(\r\n    cfg: DictConfig,\r\n    data_cfg: DictConfig | None,\r\n    training_order: str = \"degrevlex\",\r\n):\r\n    \"\"\"\r\n    Build the load-time preprocessor chain that converts raw text data into the\r\n    string form expected by the tokenizer. Used by both run_training() and the\r\n    offline preprocess.py script so the two stay in sync.\r\n\r\n    Chain composition:\r\n      training_order=lex   → TextToSage + GroebnerLexOrder\r\n      lexer format=expanded → TextToSage + ExpandedForm (appended)\r\n\r\n    Returns\r\n    -------\r\n    tuple (preprocessor_or_None, format_str)\r\n        preprocessor is None when no preprocessing is needed (raw text + degrevlex).\r\n        format_str is \"raw\" or \"expanded\" for logging.\r\n    \"\"\"\r\n    lexer_format = detect_lexer_format(cfg.data.lexer_config)\r\n    needs_ring = (training_order == \"lex\") or (lexer_format == \"expanded\")\r\n    R_src = _build_source_ring(data_cfg) if (needs_ring and data_cfg is not None) else None\r\n    if needs_ring and R_src is None:\r\n        raise ValueError(\r\n            \"Either training_order='lex' or lexer format='expanded' requires data_cfg \"\r\n            \"to rebuild the source ring.\"\r\n        )\r\n\r\n    chain = []\r\n    if training_order == \"lex\":\r\n        chain.append(TextToSageLoadPreprocessor(delimiter=\"|\", ring=R_src))\r\n        chain.append(GroebnerLexOrderPreprocessor(R_src, delimiter=\"|\"))\r\n    if lexer_format == \"expanded\":\r\n        if not chain:\r\n            chain.append(TextToSageLoadPreprocessor(delimiter=\"|\", ring=R_src))\r\n        chain.append(ExpandedFormLoadPreprocessor(delimiter=\" | \"))\r\n\r\n    # Wire optional user post-processing hooks (task 3).\r\n    # - shared/base_postprocessor.py   (applies to all tasks)\r\n    # - groebner_basis/core/postprocessor.py (per-task, runs after base)\r\n    # Both are opt-in: if neither file exists, this branch is a no-op.\r\n    from shared.user_postprocessor import (\r\n        get_user_postprocessors,\r\n        RawLineToTupleAdapter,\r\n        UserPostProcessorAdapter,\r\n    )\r\n    user_hooks = get_user_postprocessors(\"groebner_basis\")\r\n    if user_hooks:\r\n        # If no task chain step has run yet, parse the raw line first so the\r\n        # hooks receive a (str, str) tuple.\r\n        if not chain:\r\n            chain.append(RawLineToTupleAdapter())\r\n        chain.append(UserPostProcessorAdapter(user_hooks))\r\n\r\n    if not chain:\r\n        return None, lexer_format\r\n    if len(chain) == 1:\r\n        return chain[0], lexer_format\r\n    return ChainLoadPreprocessor(*chain), lexer_format\r\n\r\n\r\ndef run_training(\r\n    cfg: DictConfig,\r\n    data_cfg: DictConfig | None = None,\r\n    training_order: str = \"degrevlex\",\r\n    dryrun: bool = False,\r\n) -> float:\r\n    \"\"\"\r\n    Run the full training pipeline for the Gröbner basis task.\r\n\r\n    Parameters\r\n    ----------\r\n    cfg : DictConfig\r\n        Loaded train.yaml (must contain 'model', 'train', 'data' sections).\r\n    data_cfg : DictConfig | None\r\n        Loaded data.yaml (required when training_order='lex' to rebuild the ring).\r\n    training_order : \"degrevlex\" | \"lex\"\r\n        'degrevlex' uses the stored basis as-is.\r\n        'lex' converts F,G to lex order at load time and recomputes the basis.\r\n    dryrun : bool\r\n        Reduced settings for a fast smoke test.\r\n\r\n    Returns\r\n    -------\r\n    float\r\n        Exact-match success rate on the test set (between 0 and 1).\r\n    \"\"\"\r\n    if dryrun:\r\n        apply_dryrun_settings(cfg)\r\n\r\n    save_dir = cfg.train.get(\"save_dir\", cfg.train.get(\"output_dir\", \"./results\"))\r\n    save_dir = save_dir.rstrip(\"/\") + f\"_{training_order}\"\r\n    cfg.train.save_dir = save_dir\r\n\r\n    if (\r\n        hasattr(cfg.train, \"wandb\")\r\n        and hasattr(cfg.train.wandb, \"name\")\r\n        and cfg.train.wandb.name\r\n    ):\r\n        cfg.train.wandb.name = f\"{cfg.train.wandb.name}_{training_order}\"\r\n\r\n    os.makedirs(save_dir, exist_ok=True)\r\n    OmegaConf.save(cfg, os.path.join(save_dir, \"train.yaml\"))\r\n\r\n    # ---- Cache hierarchy ----\r\n    # 1. Pre-tokenized cache (input_ids on disk) → ZERO online tokenization.\r\n    # 2. Strings cache (post-load-preprocessor strings) → tokenization still online,\r\n    #    but SageMath/FGLM/Expanded skipped.\r\n    # 3. Raw .txt + load_preprocessor (original CALT behavior).\r\n    from calt.preprocess import (\r\n        maybe_use_pretokenized_cache,\r\n        maybe_use_processed_cache,\r\n    )\r\n    from shared.user_postprocessor import user_postprocessor_hash_contribution\r\n    hooks_hash = user_postprocessor_hash_contribution(\"groebner_basis\")\r\n\r\n    load_preprocessor, lexer_format = build_load_preprocessor(cfg, data_cfg, training_order)\r\n\r\n    used_pretok = maybe_use_pretokenized_cache(cfg, data_cfg, training_order, lexer_format, extra_hash_bytes=hooks_hash)\r\n    if used_pretok:\r\n        print(f\"[run_training] using PRE-TOKENIZED cache (format={lexer_format}, order={training_order})\")\r\n        io_pipeline = IOPipeline.from_config(cfg.data)\r\n    else:\r\n        used_strings = maybe_use_processed_cache(cfg, data_cfg, training_order, lexer_format, extra_hash_bytes=hooks_hash)\r\n        if used_strings:\r\n            print(f\"[run_training] using strings cache (format={lexer_format}, order={training_order})\")\r\n            io_pipeline = IOPipeline.from_config(cfg.data)\r\n        else:\r\n            io_pipeline = IOPipeline.from_config(cfg.data)\r\n            if load_preprocessor is not None:\r\n                io_pipeline.dataset_load_preprocessor = load_preprocessor\r\n            print(f\"[run_training] no cache; lexer format={lexer_format}, training_order={training_order}\")\r\n\r\n    io_dict = io_pipeline.build()\r\n\r\n    model = ModelPipeline.from_io_dict(cfg.model, io_dict).build()\r\n    trainer_pipeline = TrainerPipeline.from_io_dict(cfg.train, model, io_dict).build()\r\n\r\n    trainer_pipeline.train()\r\n    trainer_pipeline.save_model()\r\n    return trainer_pipeline.evaluate_and_save_generation()\r\n","groebner_basis/core/__init__.py":"from .generator import GroebnerGenerator\r\nfrom .formatter import format_input, format_target\r\nfrom .parser import GroebnerLexOrderPreprocessor\r\nfrom .metrics import success_rate\r\nfrom .train import run_training\r\n\r\n__all__ = [\r\n    \"GroebnerGenerator\",\r\n    \"format_input\",\r\n    \"format_target\",\r\n    \"GroebnerLexOrderPreprocessor\",\r\n    \"success_rate\",\r\n    \"run_training\",\r\n]\r\n","groebner_basis/experiments/ablation/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 6\r\n  num_encoder_heads: 8\r\n  num_decoder_layers: 6\r\n  num_decoder_heads: 8\r\n  d_model: 512\r\n  encoder_ffn_dim: 2048\r\n  decoder_ffn_dim: 2048\r\n  max_sequence_length: 2048\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 100\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 32\r\n  test_batch_size: 32\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 4\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: groebner_basis_ablation\r\n    name: ablation_placeholder\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../../toy/data/QQ/train_raw.txt\r\n  test_dataset_path: ../../toy/data/QQ/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","groebner_basis/experiments/ablation/README.md":"# Gröbner basis — ablation experiment\r\n\r\n**Goal**: study how training monomial order affects exact-match accuracy.\r\n\r\n| Knob | Choices |\r\n|------|---------|\r\n| `--training_order` | `degrevlex` (use stored basis as-is), `lex` (FGLM at load time) |\r\n\r\nLex bases are typically larger and have larger coefficients, so accuracy is\r\nexpected to drop vs degrevlex (see Table 5 of the ISSAC2026 paper: 42.4% degrevlex\r\nvs 32.4% lex on QQ).\r\n\r\n**Implementation note**: the lex Gröbner basis is computed at load time with\r\n`libsingular:std` explicitly (`core/parser.py`). The default `stdhilb` algorithm\r\nin SageMath 10.6 raises an `intvec` / `bigintvec` error on some QQ-lex inputs;\r\nforcing `libsingular:std` is the standard workaround.\r\n\r\n## How to run\r\n```bash\r\ncd groebner_basis/experiments/ablation/scripts\r\npython train.py --training_order degrevlex\r\npython train.py --training_order lex\r\n```\r\n\r\nReuses the dataset generated by the toy experiment (`../../toy/data/QQ/`).\r\nSave dirs are auto-suffixed with `_degrevlex` / `_lex` to avoid clobbering.\r\n","groebner_basis/experiments/ablation/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","groebner_basis/experiments/ablation/scripts/train.py":"\"\"\"Gröbner basis ablation: degrevlex vs lex training order.\r\n\r\nUsage: python train.py --training_order {degrevlex,lex}\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom groebner_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--training_order\",\r\n    type=click.Choice([\"degrevlex\", \"lex\"]),\r\n    default=\"degrevlex\",\r\n)\r\n@click.option(\"--dryrun\", is_flag=True)\r\ndef main(training_order: str, dryrun: bool) -> None:\r\n    cfg = OmegaConf.load(config_dir(__file__) / \"train.yaml\")\r\n\r\n    data_cfg = None\r\n    if training_order == \"lex\":\r\n        # Reuse the toy data config so we know the source ring.\r\n        data_cfg = OmegaConf.load(config_dir(__file__).parent.parent / \"toy/configs/data.yaml\")\r\n\r\n    cfg.train.wandb.name = \"ablation\"\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, data_cfg=data_cfg, training_order=training_order, dryrun=dryrun)\r\n    print(f\"[{training_order}] Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/experiments/scaling/configs/data.yaml":"# Groebner scaling: larger dataset and harder polynomials than toy/.\r\n\r\nsampler:\r\n  symbols: \"x,y\"\r\n  field_str: \"QQ\"\r\n  order: \"degrevlex\"\r\n  max_num_terms: 6\r\n  max_degree: 5\r\n  min_degree: 1\r\n  max_coeff: 5\r\n  degree_sampling: \"uniform\"\r\n  term_sampling: \"uniform\"\r\n\r\nproblem_generator:\r\n  num_polynomials: 2\r\n\r\ndataset:\r\n  save_dir: \"../data/QQ\"\r\n  num_train_samples: 50000\r\n  num_test_samples: 1000\r\n  batch_size: 1000\r\n  n_jobs: 8\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sagemath\"\r\n  save_text: true\r\n  save_json: false\r\n","groebner_basis/experiments/scaling/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 6\r\n  num_encoder_heads: 8\r\n  num_decoder_layers: 6\r\n  num_decoder_heads: 8\r\n  d_model: 512\r\n  encoder_ffn_dim: 2048\r\n  decoder_ffn_dim: 2048\r\n  max_sequence_length: 2048\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 200\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 64\r\n  test_batch_size: 64\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 4\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: groebner_basis\r\n    name: scaling_large\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/QQ/train_raw.txt\r\n  test_dataset_path: ../data/QQ/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","groebner_basis/experiments/scaling/README.md":"# Gröbner basis — scaling experiment\r\n\r\n**Goal**: study how exact-match accuracy scales with model size and dataset size.\r\n\r\n| Knob | Choices |\r\n|------|---------|\r\n| `--model_size` | `small`, `medium`, `large` |\r\n| `--training_order` | `degrevlex` (default), `lex` (FGLM at load time) |\r\n\r\n## What this experiment varies vs `toy/`\r\n- Larger dataset: 50k train / 1k test (vs 1k / 200)\r\n- Harder polynomials: `max_degree=5`, `max_num_terms=6`\r\n- Configurable model size via CLI\r\n\r\n## How to run\r\n```bash\r\ncd groebner_basis/experiments/scaling/scripts\r\npython generate.py\r\npython train.py --model_size small\r\npython train.py --model_size large --training_order lex\r\n```\r\n","groebner_basis/experiments/scaling/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","groebner_basis/experiments/scaling/scripts/generate.py":"\"\"\"Generate the large-scale Gröbner basis dataset for the scaling experiment.\r\n\r\nReference: issac2026_experiments/groebner/generate_dataset.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\nfrom groebner_basis.core.generator import GroebnerGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\"--config_path\", type=click.Path(exists=True), default=None)\r\ndef main(config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    sampler_cfg = dict(OmegaConf.to_container(cfg.sampler, resolve=True))\r\n    sampler = PolynomialSampler(**sampler_cfg)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = GroebnerGenerator(sampler=sampler, **gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(\"Dataset generation completed\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/experiments/scaling/scripts/train.py":"\"\"\"Gröbner basis scaling: vary model size to study scaling behavior.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom groebner_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\nMODEL_SIZES = {\r\n    \"small\":  dict(d_model=128, num_encoder_layers=2, num_decoder_layers=2,\r\n                   encoder_ffn_dim=512, decoder_ffn_dim=512,\r\n                   num_encoder_heads=4, num_decoder_heads=4),\r\n    \"medium\": dict(d_model=256, num_encoder_layers=4, num_decoder_layers=4,\r\n                   encoder_ffn_dim=1024, decoder_ffn_dim=1024,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n    \"large\":  dict(d_model=512, num_encoder_layers=6, num_decoder_layers=6,\r\n                   encoder_ffn_dim=2048, decoder_ffn_dim=2048,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n}\r\n\r\n\r\n@click.command()\r\n@click.option(\"--model_size\", type=click.Choice(list(MODEL_SIZES)), default=\"large\")\r\n@click.option(\"--training_order\", type=click.Choice([\"degrevlex\", \"lex\"]), default=\"degrevlex\")\r\n@click.option(\"--dryrun\", is_flag=True)\r\ndef main(model_size: str, training_order: str, dryrun: bool) -> None:\r\n    cfg = OmegaConf.load(config_dir(__file__) / \"train.yaml\")\r\n    cfg.model = OmegaConf.create({**OmegaConf.to_container(cfg.model), **MODEL_SIZES[model_size]})\r\n    cfg.train.wandb.name = f\"scaling_{model_size}\"\r\n\r\n    data_cfg = None\r\n    if training_order == \"lex\":\r\n        data_cfg = OmegaConf.load(config_dir(__file__) / \"data.yaml\")\r\n\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, data_cfg=data_cfg, training_order=training_order, dryrun=dryrun)\r\n    print(f\"[{model_size}/{training_order}] Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/experiments/toy/configs/data.yaml":"# Groebner task (toy): F=[f1,f2] over QQ[x,y] -> degrevlex Gröbner basis G of (F)\r\n\r\n# PolynomialSampler parameters (consumed by GroebnerGenerator)\r\nsampler:\r\n  symbols: \"x,y\"\r\n  field_str: \"QQ\"\r\n  order: \"degrevlex\"\r\n  max_num_terms: 5\r\n  max_degree: 4\r\n  min_degree: 1\r\n  max_coeff: 5\r\n  degree_sampling: \"uniform\"\r\n  term_sampling: \"uniform\"\r\n\r\n# GroebnerGenerator-specific parameters\r\nproblem_generator:\r\n  num_polynomials: 2\r\n\r\n# DatasetPipeline parameters\r\ndataset:\r\n  save_dir: \"../data/QQ\"\r\n  num_train_samples: 1000\r\n  num_test_samples: 200\r\n  batch_size: 100\r\n  n_jobs: 4\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sagemath\"\r\n  save_text: true\r\n  save_json: false\r\n","groebner_basis/experiments/toy/configs/lexer.yaml":"vocab:\r\n  range:\r\n    numbers: [\"\", -100, 100]\r\n  misc: [\"+\", \"-\", \"*\", \"^\", \"x\", \"y\", \"|\", \"/\"]\r\n  special_tokens: {}\r\n  flags:\r\n    include_base_vocab: true\r\n    include_base_special_tokens: true\r\n\r\nnumber_policy:\r\n  attach_sign: true\r\n  digit_group: 1        # tokenize each digit separately → handles any coefficient size\r\n  allow_float: false\r\n\r\nstrict: true\r\ninclude_base_vocab: true\r\n","groebner_basis/experiments/toy/configs/lexer_expanded.yaml":"# Lexer EXPANDED — C/E form for the Gröbner basis task.\r\n#\r\n# Each monomial is tokenized as:\r\n#   C<coeff> E<exp_x> E<exp_y>     for one term in 2 variables (x, y)\r\n# Polynomials within a sample are separated by ' | '.\r\n# Terms within a polynomial are separated by ' + ' (sign attached to the coefficient).\r\n#\r\n# Example: \"2*x^2*y + 5*x - 7\" → \"C2 E2 E1 + C5 E1 E0 + C-7 E0 E0\"\r\n#\r\n# To use this format instead of the default raw text format, point train.yaml's\r\n# data.lexer_config to this file instead of lexer.yaml.\r\n#\r\n# Reference: ISSAC '26 paper §2.2 + issac2026_experiments/polynomial_reduction/configs/.\r\n\r\nvocab:\r\n  range:\r\n    coefficients: [\"C\", -99, 99]  # coefficient range (must cover everything you see)\r\n    exponents:    [\"E\", 0, 5]     # exponent per variable (max_degree=4 in our config, with safety margin)\r\n  misc: [\"+\", \"|\"]\r\n  special_tokens: {}\r\n  flags:\r\n    include_base_vocab: true\r\n    include_base_special_tokens: true\r\n\r\nnumber_policy:\r\n  attach_sign: true\r\n  digit_group: 0\r\n  allow_float: false\r\n\r\nstrict: true\r\ninclude_base_vocab: true\r\n","groebner_basis/experiments/toy/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 3\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 3\r\n  num_decoder_heads: 4\r\n  d_model: 256\r\n  encoder_ffn_dim: 1024\r\n  decoder_ffn_dim: 1024\r\n  max_sequence_length: 2048\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 50\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.0\r\n  warmup_ratio: 0.05\r\n  batch_size: 16\r\n  test_batch_size: 16\r\n  lr_scheduler_type: linear\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 2\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: groebner_basis\r\n    name: toy_QQ\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/QQ/train_raw.txt\r\n  test_dataset_path: ../data/QQ/test_raw.txt\r\n  lexer_config: ../configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","groebner_basis/experiments/toy/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%  ({sum(g == r for g, r in zip(generated, references))}/{len(references)})\")\r\n\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","groebner_basis/experiments/toy/scripts/generate.py":"\"\"\"Generate the Gröbner basis dataset for the toy experiment.\r\n\r\nReference: issac2026_experiments/groebner/generate_dataset.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\nfrom calt.dataset.sagemath.utils.polynomial_sampler import PolynomialSampler\r\n\r\nfrom groebner_basis.core.generator import GroebnerGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml).\",\r\n)\r\ndef main(config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    sampler_cfg = dict(OmegaConf.to_container(cfg.sampler, resolve=True))\r\n    sampler = PolynomialSampler(**sampler_cfg)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = GroebnerGenerator(sampler=sampler, **gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(\"Dataset generation completed\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/experiments/toy/scripts/preprocess.py":"\"\"\"Materialize a JSONL preprocessing cache for the toy Gröbner experiment.\r\n\r\nRuns the load-time chain (TextToSage / FGLM-lex / ExpandedForm — whichever applies\r\nto your training_order + lexer.yaml) ONCE over train_raw.txt + test_raw.txt and\r\nwrites the result to `<data>/processed_<order>_<format>/`. Training will detect\r\nthe cache automatically and skip the SageMath/FGLM step on subsequent runs.\r\n\r\nRe-run this script whenever you change lexer.yaml, data.yaml's sampler, or the\r\n--training_order. The cache is hash-keyed so a stale cache is detected and\r\nignored (train.py falls back to raw + on-the-fly preprocessing).\r\n\r\nUsage\r\n-----\r\n    cd groebner_basis/experiments/toy/scripts\r\n    python preprocess.py                          # degrevlex + lexer from train.yaml\r\n    python preprocess.py --training_order lex     # build the lex cache\r\n    python preprocess.py --force                  # rebuild even if hash matches\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom groebner_basis.core.train import build_load_preprocessor\r\nfrom shared.paths import config_dir\r\nfrom shared.user_postprocessor import user_postprocessor_hash_contribution\r\nfrom calt.preprocess import preprocess_to_ids, run_preprocess\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML (defaults to ../configs/train.yaml).\",\r\n)\r\n@click.option(\r\n    \"--data_config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml).\",\r\n)\r\n@click.option(\r\n    \"--training_order\",\r\n    type=click.Choice([\"degrevlex\", \"lex\"]),\r\n    default=\"degrevlex\",\r\n    help=\"Monomial order: must match what you'll pass to train.py.\",\r\n)\r\n@click.option(\"--force\", is_flag=True, help=\"Rebuild even if hash matches.\")\r\n@click.option(\r\n    \"--pretokenize/--no-pretokenize\",\r\n    default=True,\r\n    help=\"Pre-tokenize all the way to input_ids (default ON). \"\r\n         \"OFF stores post-load-preprocessor strings only; training still tokenizes online.\",\r\n)\r\ndef main(\r\n    config_path: str | None,\r\n    data_config_path: str | None,\r\n    training_order: str,\r\n    force: bool,\r\n    pretokenize: bool,\r\n) -> None:\r\n    \"\"\"Preprocess raw .txt → JSONL cache for fast training startup.\"\"\"\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n\r\n    data_path = Path(data_config_path) if data_config_path else config_dir(__file__) / \"data.yaml\"\r\n    data_cfg = OmegaConf.load(data_path)\r\n\r\n    load_preprocessor, lexer_format = build_load_preprocessor(cfg, data_cfg, training_order)\r\n    hooks_hash = user_postprocessor_hash_contribution(\"groebner_basis\")\r\n    if pretokenize:\r\n        cache_dir = preprocess_to_ids(\r\n            cfg, data_cfg, training_order, lexer_format, load_preprocessor,\r\n            force=force, extra_hash_bytes=hooks_hash,\r\n        )\r\n    else:\r\n        cache_dir = run_preprocess(\r\n            cfg, data_cfg, training_order, lexer_format, load_preprocessor,\r\n            force=force, extra_hash_bytes=hooks_hash,\r\n        )\r\n    print(f\"[done] cache at: {cache_dir}\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/experiments/toy/scripts/run.sh":"#!/bin/bash\r\n# Run the full groebner_basis/toy experiment end-to-end.\r\n# Usage:  bash run.sh [--dryrun]\r\n\r\nset -e\r\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\r\ncd \"$SCRIPT_DIR\"\r\n\r\necho \"=== Step 1/3: Generate data ===\"\r\npython generate.py\r\n\r\necho \"=== Step 2/3: Train ===\"\r\npython train.py \"$@\"\r\n\r\necho \"=== Step 3/3: Evaluate ===\"\r\npython evaluate.py\r\n","groebner_basis/experiments/toy/scripts/train.py":"\"\"\"Train the Gröbner basis model for the toy experiment.\r\n\r\nReference: issac2026_experiments/groebner/train.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom groebner_basis.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML (defaults to ../configs/train.yaml).\",\r\n)\r\n@click.option(\r\n    \"--data_config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml). Used for lex training_order.\",\r\n)\r\n@click.option(\r\n    \"--training_order\",\r\n    type=click.Choice([\"degrevlex\", \"lex\"]),\r\n    default=\"degrevlex\",\r\n    help=\"Monomial order: degrevlex (default) or lex (FGLM at load time).\",\r\n)\r\n@click.option(\"--dryrun\", is_flag=True, help=\"Reduced settings for a fast smoke test.\")\r\ndef main(\r\n    config_path: str | None,\r\n    data_config_path: str | None,\r\n    training_order: str,\r\n    dryrun: bool,\r\n) -> None:\r\n    \"\"\"Train a Transformer to compute Gröbner bases from polynomial generators.\"\"\"\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.train.seed)\r\n\r\n    data_cfg = None\r\n    if training_order == \"lex\":\r\n        data_path = Path(data_config_path) if data_config_path else config_dir(__file__) / \"data.yaml\"\r\n        data_cfg = OmegaConf.load(data_path)\r\n\r\n    success = run_training(cfg, data_cfg=data_cfg, training_order=training_order, dryrun=dryrun)\r\n    print(f\"Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","groebner_basis/README.md":"# groebner_basis\r\n\r\n**Task**: Given a polynomial f and generators g1, g2, g3, predict the remainder\r\nof f on division by the Gröbner basis of the ideal ⟨g1, g2, g3⟩.\r\n\r\n## The math\r\n\r\nLet R = ℤ[x, y, z] and I = ⟨g1, g2, g3⟩ ⊂ R.\r\n\r\n1. Compute G = grevlex Gröbner basis of I  (using Buchberger's algorithm).\r\n2. Compute r = I.reduce(f)  (remainder of the division of f by G).\r\n\r\nThe model receives (f, G) as input and must predict r.\r\n\r\n**Why is this hard?** Even knowing G, computing r requires a multi-step\r\npolynomial division algorithm. The model must learn this algorithm implicitly.\r\n\r\n## Data\r\n\r\n- Field: ℤ (integers)\r\n- Variables: x, y, z\r\n- Polynomials: 2–5 terms, degree ≤ 4, coefficients in [-10, 10]\r\n- Stored as: pickle (SageMath objects)\r\n\r\n## Experiments\r\n\r\n| Experiment | What varies |\r\n|---|---|\r\n| `toy/` | Small model, 1000 train samples — verify the pipeline runs |\r\n| `scaling/` | Larger models and datasets — measure scaling behavior |\r\n| `ablation/` | Order (grevlex vs. lex), pattern (remainder vs. quotients+remainder) |\r\n\r\n## Quick start\r\n\r\n```bash\r\ncd groebner_basis/experiments/toy/scripts\r\npython generate.py          # generate data  (~1 min)\r\npython train.py             # train model    (~10 min on GPU)\r\npython evaluate.py          # evaluate       (prints success rate)\r\n```\r\n\r\nOr run everything:\r\n\r\n```bash\r\nbash run.sh\r\n```\r\n\r\n## Offline preprocessing (optional, recommended for `lex` order)\r\n\r\n`train.py` applies the `dataset_load_preprocessor` (TextToSage → FGLM for lex,\r\nTextToSage → ExpandedForm for C/E format) **every time it starts**. For large\r\ndatasets and the `lex` chain that means several minutes of SageMath/FGLM\r\nrecomputation before each run.\r\n\r\n`preprocess.py` runs that chain **once** offline and writes a JSONL cache. By\r\ndefault it also pre-tokenizes all the way to `input_ids` so that `train.py`\r\nperforms **zero tokenization at runtime** — only padding + GPU forward.\r\n\r\n```bash\r\ncd groebner_basis/experiments/toy/scripts\r\npython preprocess.py                          # cache (pretokenized) for degrevlex\r\npython preprocess.py --training_order lex     # cache (pretokenized) for lex order\r\npython preprocess.py --no-pretokenize         # cache stops at post-FGLM strings (legacy mode)\r\npython train.py --training_order lex          # auto-detects cache → fast startup\r\n```\r\n\r\nTwo cache flavors live side-by-side; `train.py` prefers the pre-tokenized one:\r\n\r\n| Cache directory | Contains | Skipped at training time |\r\n|---|---|---|\r\n| `processed_<order>_<format>_ids/` | `{\"input_ids\": [...], \"target_ids\": [...]}` | SageMath + UnifiedLexer + HF tokenizer |\r\n| `processed_<order>_<format>/`     | `{\"problem\": str, \"answer\": str}`         | SageMath only (lexer/tokenizer still online) |\r\n| (none)                            | raw `.txt`                                | nothing — legacy path |\r\n\r\nThe caches live next to your raw `.txt`:\r\n\r\n```\r\ndata/QQ/\r\n├── train_raw.txt\r\n├── test_raw.txt\r\n├── processed_lex_raw_ids/         ← pre-tokenized (default --pretokenize)\r\n│   ├── train_ids.jsonl            ← {\"input_ids\":[...], \"target_ids\":[...]}\r\n│   ├── test_ids.jsonl\r\n│   ├── _hash.txt                  ← includes tokenizer vocab in the hash\r\n│   └── _meta.yaml\r\n└── processed_lex_raw/             ← strings cache (--no-pretokenize)\r\n    ├── train_processed.jsonl\r\n    ├── test_processed.jsonl\r\n    ├── _hash.txt\r\n    └── _meta.yaml\r\n```\r\n\r\n**When to re-run `preprocess.py`** — any change to `lexer.yaml`, `data.yaml`\r\nsampler config, or the `--training_order` produces a new hash. `train.py`\r\ndetects the mismatch automatically and falls back to the slow path, printing\r\na `cache is STALE` warning. Re-run `preprocess.py` (or `--force`) to refresh.\r\n\r\n**When NOT to bother** — for `--training_order degrevlex` with the default raw\r\nlexer there is no load-time work to skip (the chain is empty), so the cache\r\njust copies the raw text. Still safe to use, but the speedup is zero.\r\n\r\n## User post-processing hooks (optional)\r\n\r\nTwo opt-in slots let you inject custom transformations of `(input_text, target_text)`\r\nafter the load chain (FGLM/Expanded/etc.) has run, before tokenization:\r\n\r\n| Slot | File (create to enable) | Scope |\r\n|---|---|---|\r\n| Base hook   | `shared/base_postprocessor.py`         | Applied to every task that wires user hooks (groebner + border) |\r\n| Per-task    | `groebner_basis/core/postprocessor.py` | Applied to groebner only, AFTER the base hook |\r\n\r\nEach file must expose:\r\n\r\n```python\r\ndef postprocess(input_text: str, target_text: str) -> tuple[str, str]:\r\n    return input_text, target_text  # default: identity\r\n```\r\n\r\nTo enable, copy the corresponding `.py.example` file:\r\n\r\n```bash\r\ncp shared/base_postprocessor.py.example shared/base_postprocessor.py\r\n# then edit shared/base_postprocessor.py\r\n```\r\n\r\nThe hook source code is folded into the preprocessing cache hash, so editing\r\n`postprocess()` automatically invalidates stale caches — your next\r\n`preprocess.py` run rebuilds them. If you delete the file the system reverts\r\nto identity (no hook).\r\n\r\nExamples and caveats are in [shared/base_postprocessor.py.example](../shared/base_postprocessor.py.example).\r\n\r\n## Variants\r\n\r\n- `--order lex` : convert to lex order via FGLM before training\r\n- `--pattern 2` : predict quotients + remainder instead of remainder only\r\n\r\n## Tokenization format (raw vs C/E expanded)\r\n\r\nTwo tokenization schemes are available. The training pipeline auto-detects which one\r\nto use from the `data.lexer_config` field in your `train.yaml`.\r\n\r\n| Format | Lexer config | How a term is encoded | Vocab size |\r\n|---|---|---|---|\r\n| **raw** (default) | `configs/lexer.yaml` | `\"x ^ 2 + y\"` → `[\"x\", \"^\", \"2\", \"+\", \"y\"]` | larger (one token per digit) |\r\n| **expanded** (C/E) | `configs/lexer_expanded.yaml` | `\"2*x^2*y\"` → `[\"C2\", \"E2\", \"E1\"]` | smaller, fixed |\r\n\r\n**Switching is one line**: in `experiments/<exp>/configs/train.yaml`, change\r\n\r\n```yaml\r\ndata:\r\n  lexer_config: ../configs/lexer.yaml           # raw  (default)\r\n  # lexer_config: ../configs/lexer_expanded.yaml  # C/E expanded\r\n```\r\n\r\nThat's it. `core/train.py` calls `detect_lexer_format()` on the file and wires\r\n`ExpandedFormLoadPreprocessor` into the load chain automatically when needed.\r\n\r\n**When to use which**:\r\n- **raw** — default, matches ISSAC '26 §5 reproduction. Handles coefficient swell on ℚ\r\n  via `digit_group: 1` (each digit is its own token). Use this to reproduce paper\r\n  results.\r\n- **expanded** — fixed-size vocab (only ranges `[Cmin, Cmax]` and `[Emin, Emax]`).\r\n  Useful if you want a smaller embedding table or to align with the\r\n  `polynomial_reduction` task in the ISSAC '26 paper. ⚠ Coefficients outside the\r\n  declared range produce OOV tokens — widen `coefficients` in `lexer_expanded.yaml`\r\n  if you change the field or sampler.\r\n\r\n**Caveat — combining with `--order lex`**: both modes work together. The lex\r\npreprocessor runs first (recomputes G in lex order via FGLM), then expanded form\r\nruns on the lex-ordered output. See [core/train.py](core/train.py) `run_training()`.\r\n"},"parity":{"parity/core/formatter.py":"\"\"\"\r\nConvert permutation objects to their string representations.\r\n\r\nFormat\r\n------\r\nInput  : space-separated integers — the one-line notation of σ\r\nOutput : \"+1\" (even) or \"-1\" (odd)\r\n\r\nExample:\r\n    format_input([2, 0, 1])   →  \"2 0 1\"\r\n    format_target(+1)         →  \"+1\"\r\n    format_target(-1)         →  \"-1\"\r\n\r\nWhy these tokens?\r\n-----------------\r\n\"+1\" and \"-1\" are single tokens in the CALT vocabulary (numbers with sign).\r\nThe model output space is effectively binary, which makes evaluation simple.\r\n\"\"\"\r\n\r\n\r\ndef format_input(perm: list[int]) -> str:\r\n    \"\"\"\r\n    Convert a permutation list to a space-separated string.\r\n\r\n    Example:  [2, 0, 1]  →  \"2 0 1\"\r\n    \"\"\"\r\n    return \" \".join(str(x) for x in perm)\r\n\r\n\r\ndef format_target(parity: int) -> str:\r\n    \"\"\"\r\n    Convert +1 / −1 parity to its string token.\r\n\r\n    Example:  +1  →  \"+1\"    −1  →  \"-1\"\r\n    \"\"\"\r\n    return \"+1\" if parity == 1 else \"-1\"\r\n","parity/core/generator.py":"\"\"\"\r\nGenerate (problem, answer) pairs for the permutation parity task.\r\n\r\nMath\r\n----\r\nInput  : a random permutation σ of {0, 1, …, n−1}\r\nOutput : sign(σ) ∈ {+1, −1}\r\n\r\nsign(σ) = (−1)^k   where k = number of inversions in σ\r\n\r\nAn inversion is a pair (i, j) with i < j and σ(i) > σ(j).\r\n\r\nOutput format\r\n-------------\r\nThe generator returns plain strings. The DatasetPipeline writes them to disk:\r\n  - input  : \"2 0 1\"        (space-separated one-line notation)\r\n  - output : \"+1\" or \"-1\"\r\n\r\nReference\r\n---------\r\nClass-based generator pattern matching\r\nissac2026_experiments/digit_product/generate_dataset.py\r\n(HiroshiKERA/calt@experiment/issac2026).\r\n\"\"\"\r\n\r\nimport random\r\nfrom itertools import combinations\r\n\r\n\r\ndef count_inversions(perm: list[int]) -> int:\r\n    \"\"\"Number of pairs (i, j) with i < j and perm[i] > perm[j].\"\"\"\r\n    return sum(\r\n        1 for i, j in combinations(range(len(perm)), 2)\r\n        if perm[i] > perm[j]\r\n    )\r\n\r\n\r\ndef permutation_parity(perm: list[int]) -> int:\r\n    \"\"\"+1 (even) or −1 (odd) — equals (−1)^(number of inversions).\"\"\"\r\n    return 1 if count_inversions(perm) % 2 == 0 else -1\r\n\r\n\r\nclass ParityGenerator:\r\n    \"\"\"\r\n    Problem generator: random permutation σ of {0,…,n−1}, answer is sign(σ).\r\n\r\n    Parameters\r\n    ----------\r\n    n : int\r\n        Permutation length (default 5).\r\n    \"\"\"\r\n\r\n    def __init__(self, n: int = 5):\r\n        if n < 1:\r\n            raise ValueError(f\"n must be ≥ 1, got {n}\")\r\n        self.n = n\r\n\r\n    def __call__(self, seed: int) -> tuple[str, str]:\r\n        random.seed(seed)\r\n        perm = list(range(self.n))\r\n        random.shuffle(perm)\r\n        parity = permutation_parity(perm)\r\n        input_str = \" \".join(str(x) for x in perm)\r\n        target_str = \"+1\" if parity == 1 else \"-1\"\r\n        return input_str, target_str\r\n","parity/core/metrics.py":"\"\"\"\r\nMetrics for the parity task.\r\n\r\nsuccess_rate() is the exact-match accuracy used after training to score the model.\r\n\"\"\"\r\n\r\n\r\ndef success_rate(predictions: list[str], targets: list[str]) -> float:\r\n    \"\"\"\r\n    Return the fraction of predictions that exactly match the target parity.\r\n\r\n    Both \"+1\" and \"-1\" are single tokens — exact match is the right metric.\r\n    \"\"\"\r\n    if not targets:\r\n        return 0.0\r\n    correct = sum(1 for p, t in zip(predictions, targets) if p.strip() == t.strip())\r\n    return correct / len(targets)\r\n","parity/core/parser.py":"\"\"\"\r\nLoad-time preprocessor for the parity task.\r\n\r\nThe default text pipeline reads \"2 0 1 # +1\" directly — no custom preprocessor is needed.\r\nThis module is reserved for future extensions.\r\n\"\"\"\r\n","parity/core/train.py":"\"\"\"\r\nTraining runner for the parity task.\r\n\r\nThe parity task uses plain-text storage (no pickle), so no custom\r\nload_preprocessor is needed — CALT's TextDefaultLoadPreprocessor handles it.\r\n\"\"\"\r\n\r\nimport os\r\n\r\nfrom omegaconf import DictConfig, OmegaConf\r\n\r\nfrom shared.calt_adapter import (\r\n    IOPipeline,\r\n    ModelPipeline,\r\n    TrainerPipeline,\r\n    apply_dryrun_settings,\r\n)\r\n\r\n\r\ndef run_training(cfg: DictConfig, dryrun: bool = False) -> float:\r\n    \"\"\"\r\n    Run the full training pipeline for the permutation parity task.\r\n\r\n    Parameters\r\n    ----------\r\n    cfg : DictConfig\r\n        Config with 'model', 'train', 'data' sections.\r\n    dryrun : bool\r\n        If True, run for 1 epoch on a tiny subset.\r\n\r\n    Returns\r\n    -------\r\n    float\r\n        Exact-match success rate on the test set.\r\n    \"\"\"\r\n    if dryrun:\r\n        apply_dryrun_settings(cfg)\r\n\r\n    save_dir = cfg.train.get(\"save_dir\", cfg.train.get(\"output_dir\", \"./results\"))\r\n    os.makedirs(save_dir, exist_ok=True)\r\n    OmegaConf.save(cfg, os.path.join(save_dir, \"train.yaml\"))\r\n\r\n    # No custom preprocessor: text format is handled automatically\r\n    io_dict = IOPipeline.from_config(cfg.data).build()\r\n    model = ModelPipeline.from_io_dict(cfg.model, io_dict).build()\r\n    trainer_pipeline = TrainerPipeline.from_io_dict(cfg.train, model, io_dict).build()\r\n\r\n    trainer_pipeline.train()\r\n    trainer_pipeline.save_model()\r\n    return trainer_pipeline.evaluate_and_save_generation()\r\n","parity/core/__init__.py":"from .generator import ParityGenerator, count_inversions, permutation_parity\r\nfrom .formatter import format_input, format_target\r\nfrom .metrics import success_rate\r\nfrom .train import run_training\r\n\r\n__all__ = [\r\n    \"ParityGenerator\",\r\n    \"count_inversions\",\r\n    \"permutation_parity\",\r\n    \"format_input\",\r\n    \"format_target\",\r\n    \"success_rate\",\r\n    \"run_training\",\r\n]\r\n","parity/experiments/ablation/configs/train.yaml":"# Parity ablation — train.yaml is the base; --model_size CLI overrides model/*.\r\n\r\nmodel:\r\n  model_type: generic\r\n  num_encoder_layers: 2\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 2\r\n  num_decoder_heads: 4\r\n  d_model: 128\r\n  encoder_ffn_dim: 512\r\n  decoder_ffn_dim: 512\r\n  max_sequence_length: 64\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 100\r\n  learning_rate: 0.0005\r\n  weight_decay: 0.01\r\n  warmup_ratio: 0.1\r\n  batch_size: 64\r\n  test_batch_size: 64\r\n  lr_scheduler_type: cosine\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 2\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: parity_ablation\r\n    name: ablation\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../../toy/data/train_raw.txt\r\n  test_dataset_path: ../../toy/data/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","parity/experiments/ablation/README.md":"# Parity — ablation experiment\r\n\r\n**Goal**: study which model knobs matter for permutation parity.\r\n\r\nVary one knob at a time over the toy dataset (`n=5`):\r\n\r\n| Knob | Choices |\r\n|------|---------|\r\n| `--model_size` | `small`, `medium`, `large` |\r\n\r\n## How to run\r\n```bash\r\ncd parity/experiments/ablation/scripts\r\n# Reuses the dataset generated by the toy experiment\r\npython train.py --model_size small\r\npython train.py --model_size large\r\n```\r\n\r\nOutputs land in `outputs/results_<model_size>/` so successive runs do not overwrite.\r\n","parity/experiments/ablation/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","parity/experiments/ablation/scripts/train.py":"\"\"\"Ablation: vary the model size for the parity task.\r\n\r\nUsage: python train.py --model_size {small,medium,large}\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom parity.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\nMODEL_SIZES = {\r\n    \"small\":  dict(d_model=64,  num_encoder_layers=2, num_decoder_layers=2,\r\n                   encoder_ffn_dim=256, decoder_ffn_dim=256,\r\n                   num_encoder_heads=4, num_decoder_heads=4),\r\n    \"medium\": dict(d_model=128, num_encoder_layers=4, num_decoder_layers=4,\r\n                   encoder_ffn_dim=512, decoder_ffn_dim=512,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n    \"large\":  dict(d_model=256, num_encoder_layers=6, num_decoder_layers=6,\r\n                   encoder_ffn_dim=1024, decoder_ffn_dim=1024,\r\n                   num_encoder_heads=8, num_decoder_heads=8),\r\n}\r\n\r\n\r\n@click.command()\r\n@click.option(\"--model_size\", type=click.Choice(list(MODEL_SIZES)), default=\"small\")\r\n@click.option(\"--dryrun\", is_flag=True)\r\ndef main(model_size: str, dryrun: bool) -> None:\r\n    cfg = OmegaConf.load(config_dir(__file__) / \"train.yaml\")\r\n    overrides = MODEL_SIZES[model_size]\r\n    cfg.model = OmegaConf.create({**OmegaConf.to_container(cfg.model), **overrides})\r\n    cfg.train.save_dir = f\"../outputs/results_{model_size}\"\r\n    cfg.train.wandb.name = f\"ablation_{model_size}\"\r\n\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, dryrun=dryrun)\r\n    print(f\"[{model_size}] Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","parity/experiments/scaling/configs/data.yaml":"# Parity scaling: larger dataset, permutation length controlled by --n CLI flag.\r\n\r\nproblem_generator:\r\n  n: 7\r\n\r\ndataset:\r\n  save_dir: \"../data\"        # generate.py overrides to \"../data_n{N}\"\r\n  num_train_samples: 50000\r\n  num_test_samples: 1000\r\n  batch_size: 5000\r\n  n_jobs: 8\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sympy\"\r\n  save_text: true\r\n  save_json: false\r\n","parity/experiments/scaling/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 4\r\n  num_encoder_heads: 8\r\n  num_decoder_layers: 4\r\n  num_decoder_heads: 8\r\n  d_model: 256\r\n  encoder_ffn_dim: 1024\r\n  decoder_ffn_dim: 1024\r\n  max_sequence_length: 128\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 200\r\n  learning_rate: 0.0003\r\n  weight_decay: 0.01\r\n  warmup_ratio: 0.1\r\n  batch_size: 256\r\n  test_batch_size: 256\r\n  lr_scheduler_type: cosine\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 4\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: parity\r\n    name: scaling_n7\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/train_raw.txt\r\n  test_dataset_path: ../data/test_raw.txt\r\n  lexer_config: ../../toy/configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","parity/experiments/scaling/README.md":"# Parity — scaling experiment\r\n\r\n**Goal**: study how exact-match accuracy scales with the permutation length `n`\r\n(harder for larger `n` because the input space is `n!`).\r\n\r\n## What it varies vs `toy/`\r\n- Larger dataset (50k train / 1k test)\r\n- `n` is selectable via CLI flag: `--n {5,7,10}`\r\n- Larger model\r\n\r\n## How to run\r\n```bash\r\ncd parity/experiments/scaling/scripts\r\npython generate.py --n 7         # generates ../data_n7/\r\npython train.py --n 7            # trains on it\r\n```\r\n\r\nThe default toy run lives in `../toy/` and uses `n=5`.\r\n","parity/experiments/scaling/scripts/evaluate.py":"\"\"\"Load a trained model and evaluate it on the test set.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%  ({sum(g == r for g, r in zip(generated, references))}/{len(references)})\")\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    print()\r\n    show_examples(generated, references, n=5, successes=False)\r\n","parity/experiments/scaling/scripts/generate.py":"\"\"\"Generate the parity scaling dataset.\r\n\r\nUsage: python generate.py --n 7\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\n\r\nfrom parity.core.generator import ParityGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\"--n\", type=int, default=None, help=\"Permutation length (overrides config).\")\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML.\",\r\n)\r\ndef main(n: int | None, config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    if n is not None:\r\n        cfg.problem_generator.n = n\r\n    cfg.dataset.save_dir = f\"../data_n{cfg.problem_generator.n}\"\r\n\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = ParityGenerator(**gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(f\"Dataset generation completed (n={cfg.problem_generator.n})\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","parity/experiments/scaling/scripts/train.py":"\"\"\"Train the parity model at a chosen permutation length.\r\n\r\nUsage: python train.py --n 7\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom parity.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\"--n\", type=int, default=None, help=\"Permutation length to train on.\")\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML.\",\r\n)\r\n@click.option(\"--dryrun\", is_flag=True, help=\"Reduced settings for a fast smoke test.\")\r\ndef main(n: int | None, config_path: str | None, dryrun: bool) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n\r\n    if n is not None:\r\n        cfg.data.train_dataset_path = f\"../data_n{n}/train_raw.txt\"\r\n        cfg.data.test_dataset_path = f\"../data_n{n}/test_raw.txt\"\r\n        cfg.train.save_dir = f\"../outputs/results_n{n}\"\r\n        if hasattr(cfg.train, \"wandb\") and hasattr(cfg.train.wandb, \"name\"):\r\n            cfg.train.wandb.name = f\"scaling_n{n}\"\r\n\r\n    set_seed(cfg.train.seed)\r\n    success = run_training(cfg, dryrun=dryrun)\r\n    print(f\"Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","parity/experiments/toy/configs/data.yaml":"# Parity task (toy): random permutation σ of {0..n-1} -> sign(σ) ∈ {+1, -1}\r\n\r\nproblem_generator:\r\n  n: 5            # permutation length (5! = 120 distinct inputs)\r\n\r\ndataset:\r\n  save_dir: \"../data\"\r\n  num_train_samples: 5000\r\n  num_test_samples: 500\r\n  batch_size: 1000\r\n  n_jobs: 4\r\n  root_seed: 42\r\n  verbose: true\r\n  backend: \"sympy\"\r\n  save_text: true\r\n  save_json: false\r\n","parity/experiments/toy/configs/lexer.yaml":"vocab:\r\n  range:\r\n    numbers: [\"\", 0, 20]          # permutation elements: 0..19 (covers n ≤ 20)\r\n    signed: [\"\", -1, -1]          # the target token \"-1\"\r\n  misc: [\"+1\"]                    # the target token \"+1\"\r\n  special_tokens: {}\r\n  flags:\r\n    include_base_vocab: true\r\n    include_base_special_tokens: true\r\n\r\nnumber_policy:\r\n  attach_sign: true\r\n  digit_group: 0\r\n  allow_float: false\r\n\r\nstrict: false\r\ninclude_base_vocab: true\r\n","parity/experiments/toy/configs/train.yaml":"model:\r\n  model_type: generic\r\n  num_encoder_layers: 2\r\n  num_encoder_heads: 4\r\n  num_decoder_layers: 2\r\n  num_decoder_heads: 4\r\n  d_model: 128\r\n  encoder_ffn_dim: 512\r\n  decoder_ffn_dim: 512\r\n  max_sequence_length: 64\r\n\r\ntrain:\r\n  save_dir: ../outputs/results\r\n  num_train_epochs: 100\r\n  learning_rate: 0.0005\r\n  weight_decay: 0.01\r\n  warmup_ratio: 0.1\r\n  batch_size: 64\r\n  test_batch_size: 64\r\n  lr_scheduler_type: cosine\r\n  max_grad_norm: 1.0\r\n  optimizer: adamw_torch\r\n  num_workers: 2\r\n  seed: 42\r\n  wandb:\r\n    project: calt-experiments\r\n    group: parity\r\n    name: toy_n5\r\n    no_wandb: false\r\n\r\ndata:\r\n  train_dataset_path: ../data/train_raw.txt\r\n  test_dataset_path: ../data/test_raw.txt\r\n  lexer_config: ../configs/lexer.yaml\r\n  validate_train_tokens: false\r\n  validate_test_tokens: false\r\n","parity/experiments/toy/scripts/evaluate.py":"\"\"\"Print evaluation results for the parity toy experiment.\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared.paths import output_dir\r\nfrom shared.plotting import load_eval_results, show_examples\r\n\r\nif __name__ == \"__main__\":\r\n    results = output_dir(__file__) / \"results\"\r\n    generated, references = load_eval_results(results)\r\n\r\n    rate = sum(g == r for g, r in zip(generated, references)) / len(references)\r\n    print(f\"Success rate: {100 * rate:.1f}%  ({sum(g == r for g, r in zip(generated, references))}/{len(references)})\")\r\n\r\n    even_total = sum(1 for r in references if r.strip() == \"+1\")\r\n    odd_total = len(references) - even_total\r\n    print(f\"  Even (+1): {even_total}  |  Odd (−1): {odd_total}\")\r\n\r\n    print()\r\n    show_examples(generated, references, n=5, successes=True)\r\n    show_examples(generated, references, n=5, successes=False)\r\n","parity/experiments/toy/scripts/generate.py":"\"\"\"Generate the parity dataset for the toy experiment.\r\n\r\nReference: class-based instance_generator pattern from\r\nissac2026_experiments/digit_product/generate_dataset.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom calt.dataset import DatasetPipeline\r\n\r\nfrom parity.core.generator import ParityGenerator\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to data config YAML (defaults to ../configs/data.yaml).\",\r\n)\r\ndef main(config_path: str | None) -> None:\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"data.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.dataset.root_seed)\r\n\r\n    gen_cfg = OmegaConf.to_container(cfg.problem_generator, resolve=True)\r\n    problem_generator = ParityGenerator(**gen_cfg)\r\n\r\n    pipeline = DatasetPipeline.from_config(\r\n        cfg.dataset,\r\n        instance_generator=problem_generator,\r\n    )\r\n    pipeline.run()\r\n    print(\"Dataset generation completed\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","parity/experiments/toy/scripts/run.sh":"#!/bin/bash\r\n# Run the full parity/toy experiment end-to-end.\r\n\r\nset -e\r\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\r\ncd \"$SCRIPT_DIR\"\r\n\r\necho \"=== Step 1/3: Generate data ===\"\r\npython generate.py\r\n\r\necho \"=== Step 2/3: Train ===\"\r\npython train.py \"$@\"\r\n\r\necho \"=== Step 3/3: Evaluate ===\"\r\npython evaluate.py\r\n","parity/experiments/toy/scripts/train.py":"\"\"\"Train the parity model for the toy experiment.\r\n\r\nReference: issac2026_experiments/digit_product/train.py.\r\n\"\"\"\r\n\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nimport click\r\nfrom omegaconf import OmegaConf\r\n\r\nfrom parity.core.train import run_training\r\nfrom shared.paths import config_dir\r\nfrom shared.seed import set_seed\r\n\r\n\r\n@click.command()\r\n@click.option(\r\n    \"--config_path\",\r\n    type=click.Path(exists=True),\r\n    default=None,\r\n    help=\"Path to train config YAML (defaults to ../configs/train.yaml).\",\r\n)\r\n@click.option(\"--dryrun\", is_flag=True, help=\"Reduced settings for a fast smoke test.\")\r\ndef main(config_path: str | None, dryrun: bool) -> None:\r\n    \"\"\"Train a Transformer to predict the sign of a permutation.\"\"\"\r\n    cfg_path = Path(config_path) if config_path else config_dir(__file__) / \"train.yaml\"\r\n    cfg = OmegaConf.load(cfg_path)\r\n    set_seed(cfg.train.seed)\r\n\r\n    success = run_training(cfg, dryrun=dryrun)\r\n    print(f\"Success rate: {100 * success:.1f}%\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","parity/README.md":"# parity\r\n\r\n**Task**: Given a permutation σ of {0, 1, …, n−1}, predict its sign: +1 (even) or −1 (odd).\r\n\r\n## The math\r\n\r\nA permutation σ is **even** if it can be written as a product of an even number\r\nof transpositions, and **odd** otherwise.\r\n\r\nEquivalently:\r\n\r\n    sign(σ) = (−1)^(number of inversions)\r\n\r\nwhere an **inversion** is a pair (i, j) with i < j but σ(i) > σ(j).\r\n\r\n**Example**:\r\n\r\n    σ = [2, 0, 1]   (σ(0)=2, σ(1)=0, σ(2)=1)\r\n    Inversions: (0,1) since σ(0)=2 > σ(1)=0\r\n                (0,2) since σ(0)=2 > σ(2)=1\r\n    2 inversions → even → sign(σ) = +1\r\n\r\n## Why this task?\r\n\r\nParity is a benchmark for learning **global** properties of sequences:\r\nthe model cannot look at any single element — it must compare all pairs.\r\nThis is known to require attention across the full sequence length.\r\n\r\n## Data format\r\n\r\nInput  : space-separated integers — the one-line notation of σ\r\nOutput : \"+1\" or \"−1\"\r\n\r\n    \"2 0 1\"  →  \"+1\"\r\n    \"3 0 2 1\"  →  \"−1\"\r\n\r\n## Experiments\r\n\r\n| Experiment | What varies |\r\n|---|---|\r\n| `toy/` | n=5 permutations, 1000 samples — verify the pipeline |\r\n| `scaling/` | n ∈ {5, 8, 12} — does performance degrade with longer sequences? |\r\n\r\n## Quick start\r\n\r\n```bash\r\ncd parity/experiments/toy/scripts\r\npython generate.py\r\npython train.py\r\npython evaluate.py\r\n```\r\n"}};

export const COMMON_FILES: Record<string, string> = {"shared/calt_adapter.py":"\"\"\"\r\nThin wrapper around the four CALT pipelines.\r\n\r\nThis module re-exports the CALT API in a single place so that task scripts\r\nonly need one import instead of four, and so that future CALT API changes\r\nonly require updating this file.\r\n\r\nThe four CALT pipelines:\r\n    DatasetPipeline  →  generate (problem, answer) pairs and write to disk\r\n    IOPipeline       →  load data, apply preprocessors, tokenize\r\n    ModelPipeline    →  build the Transformer\r\n    TrainerPipeline  →  train + evaluate\r\n\r\nTypical usage in a task's core/train.py\r\n----------------------------------------\r\n    from shared.calt_adapter import (\r\n        DatasetPipeline,\r\n        IOPipeline,\r\n        ModelPipeline,\r\n        TrainerPipeline,\r\n        apply_dryrun_settings,\r\n        detect_lexer_format,\r\n        ExpandedFormLoadPreprocessor,\r\n        ChainLoadPreprocessor,\r\n    )\r\n\"\"\"\r\n\r\nimport yaml\r\nfrom pathlib import Path\r\n\r\nfrom calt.dataset import DatasetPipeline\r\nfrom calt.io import (\r\n    ChainLoadPreprocessor,\r\n    ExpandedFormLoadPreprocessor,\r\n    IOPipeline,\r\n    TextToSageLoadPreprocessor,\r\n)\r\nfrom calt.models import ModelPipeline\r\nfrom calt.trainer import TrainerPipeline, apply_dryrun_settings\r\n\r\n__all__ = [\r\n    \"DatasetPipeline\",\r\n    \"IOPipeline\",\r\n    \"ModelPipeline\",\r\n    \"TrainerPipeline\",\r\n    \"apply_dryrun_settings\",\r\n    # Load preprocessors\r\n    \"ChainLoadPreprocessor\",\r\n    \"ExpandedFormLoadPreprocessor\",\r\n    \"TextToSageLoadPreprocessor\",\r\n    # Helpers\r\n    \"detect_lexer_format\",\r\n]\r\n\r\n\r\ndef detect_lexer_format(lexer_yaml_path: str | Path) -> str:\r\n    \"\"\"\r\n    Detect whether a lexer.yaml uses the 'raw' or 'expanded' polynomial format.\r\n\r\n    Returns\r\n    -------\r\n    \"expanded\"  if vocab.range has BOTH `coefficients` and `exponents` keys\r\n                 (e.g. `coefficients: [\"C\", -99, 99]`, `exponents: [\"E\", 0, 5]`)\r\n    \"raw\"       otherwise (default: vocab.range has just `numbers`)\r\n\r\n    Background\r\n    ----------\r\n    Polynomials can be tokenized in two ways (see paper §2.2):\r\n      - raw      : text-direct, e.g. \"x ^ 2 + y\" (used by ISSAC2026/groebner)\r\n      - expanded : C/E form,   e.g. \"C1 E2 E0 + C1 E0 E1\" (used by ISSAC2026/polynomial_reduction)\r\n\r\n    The vocabulary required differs between the two formats. By inspecting the\r\n    `vocab.range` keys, we can detect which format the user wants:\r\n\r\n        vocab.range.numbers      → raw text format\r\n        vocab.range.coefficients → C/E expanded format\r\n        vocab.range.exponents    → C/E expanded format\r\n\r\n    \"\"\"\r\n    with open(lexer_yaml_path) as f:\r\n        cfg = yaml.safe_load(f) or {}\r\n    rng = (cfg.get(\"vocab\") or {}).get(\"range\") or {}\r\n    if \"coefficients\" in rng and \"exponents\" in rng:\r\n        return \"expanded\"\r\n    return \"raw\"\r\n\r\n\r\ndef maybe_wrap_with_expanded_preprocessor(\r\n    io_pipeline,\r\n    lexer_yaml_path: str | Path,\r\n    *,\r\n    delimiter: str = \"|\",\r\n    ring=None,\r\n):\r\n    \"\"\"\r\n    If the lexer is in C/E expanded format, wire `ExpandedFormLoadPreprocessor`\r\n    into the io_pipeline's load chain. Otherwise leave the pipeline unchanged.\r\n\r\n    The chain becomes:\r\n        [existing dataset_load_preprocessor if any]\r\n        → TextToSageLoadPreprocessor (raw text → Sage polynomials)\r\n        → ExpandedFormLoadPreprocessor (Sage polys → \"C1 E2 E0\" text)\r\n\r\n    Parameters\r\n    ----------\r\n    io_pipeline : IOPipeline\r\n        Mutated in place if expanded format is detected.\r\n    lexer_yaml_path : str | Path\r\n        Path to the lexer.yaml whose format determines the behavior.\r\n    delimiter : str\r\n        Inner separator between polynomials (default \"|\").\r\n    ring : sage PolynomialRing or None\r\n        Required for TextToSageLoadPreprocessor when format is expanded.\r\n        Must be provided by the caller (different rings per task).\r\n\r\n    Returns\r\n    -------\r\n    str : the detected format (\"raw\" or \"expanded\"), for logging.\r\n    \"\"\"\r\n    fmt = detect_lexer_format(lexer_yaml_path)\r\n    if fmt != \"expanded\":\r\n        return fmt\r\n    if ring is None:\r\n        raise ValueError(\r\n            \"Expanded format requires a `ring` argument to TextToSageLoadPreprocessor. \"\r\n            \"Pass the SageMath PolynomialRing matching your data.\"\r\n        )\r\n    text_to_sage = TextToSageLoadPreprocessor(delimiter=delimiter, ring=ring)\r\n    expanded_form = ExpandedFormLoadPreprocessor(delimiter=delimiter)\r\n    existing = io_pipeline.dataset_load_preprocessor\r\n    if existing is None:\r\n        io_pipeline.dataset_load_preprocessor = ChainLoadPreprocessor(text_to_sage, expanded_form)\r\n    else:\r\n        # Insert expanded_form at the end of the existing chain\r\n        io_pipeline.dataset_load_preprocessor = ChainLoadPreprocessor(existing, expanded_form)\r\n    return fmt\r\n\r\n\r\ndef run_standard_training(cfg, load_preprocessor=None, dryrun: bool = False) -> float:\r\n    \"\"\"\r\n    Run a complete training pipeline: load data → build model → train → evaluate.\r\n\r\n    Parameters\r\n    ----------\r\n    cfg : DictConfig\r\n    load_preprocessor : object | None\r\n        Optional load-time preprocessor (must implement process_sample).\r\n    dryrun : bool\r\n\r\n    Returns\r\n    -------\r\n    float : exact-match success rate on the test set.\r\n    \"\"\"\r\n    import os\r\n    from omegaconf import OmegaConf\r\n\r\n    if dryrun:\r\n        apply_dryrun_settings(cfg)\r\n\r\n    save_dir = cfg.train.get(\"save_dir\", cfg.train.get(\"output_dir\", \"./results\"))\r\n    os.makedirs(save_dir, exist_ok=True)\r\n    OmegaConf.save(cfg, os.path.join(save_dir, \"train.yaml\"))\r\n\r\n    io_pipeline = IOPipeline.from_config(cfg.data)\r\n    if load_preprocessor is not None:\r\n        io_pipeline.dataset_load_preprocessor = load_preprocessor\r\n\r\n    io_dict = io_pipeline.build()\r\n    model = ModelPipeline.from_io_dict(cfg.model, io_dict).build()\r\n    trainer_pipeline = TrainerPipeline.from_io_dict(cfg.train, model, io_dict).build()\r\n\r\n    trainer_pipeline.train()\r\n    trainer_pipeline.save_model()\r\n    return trainer_pipeline.evaluate_and_save_generation()\r\n","shared/config.py":"\"\"\"OmegaConf helpers: load YAML configs with optional command-line overrides.\"\"\"\r\n\r\nfrom pathlib import Path\r\nfrom typing import Union\r\n\r\nfrom omegaconf import DictConfig, OmegaConf\r\n\r\n\r\ndef load_config(path: Union[str, Path], overrides: list[str] | None = None) -> DictConfig:\r\n    \"\"\"\r\n    Load a YAML config file and optionally apply dot-notation overrides.\r\n\r\n    Parameters\r\n    ----------\r\n    path : str | Path\r\n        Path to the YAML config file.\r\n    overrides : list[str] | None\r\n        List of OmegaConf overrides in \"key=value\" format.\r\n        Example: [\"train.learning_rate=0.001\", \"train.num_train_epochs=50\"]\r\n\r\n    Returns\r\n    -------\r\n    DictConfig\r\n        The loaded (and optionally overridden) config.\r\n\r\n    Example\r\n    -------\r\n    >>> cfg = load_config(\"configs/train.yaml\", [\"train.batch_size=32\"])\r\n    >>> print(cfg.train.learning_rate)\r\n    \"\"\"\r\n    cfg = OmegaConf.load(path)\r\n    if overrides:\r\n        override_cfg = OmegaConf.from_dotlist(overrides)\r\n        cfg = OmegaConf.merge(cfg, override_cfg)\r\n    return cfg\r\n\r\n\r\ndef save_config(cfg: DictConfig, path: Union[str, Path]) -> None:\r\n    \"\"\"Save a config to a YAML file (useful for logging experiment settings).\"\"\"\r\n    OmegaConf.save(cfg, path)\r\n","shared/logging.py":"\"\"\"Custom HuggingFace callback that logs extra metrics to Weights & Biases.\"\"\"\r\n\r\nimport torch\r\nimport wandb\r\nfrom transformers import TrainerCallback\r\n\r\n\r\nclass CustomLoggingCallback(TrainerCallback):\r\n    \"\"\"\r\n    Log gradient norms and GPU memory usage to wandb at each logging step.\r\n\r\n    Usage\r\n    -----\r\n    Add to TrainerPipeline after building:\r\n\r\n        from shared.logging import CustomLoggingCallback\r\n        trainer_pipeline.trainer.add_callback(CustomLoggingCallback())\r\n    \"\"\"\r\n\r\n    def on_log(self, args, state, control, model=None, **kwargs):\r\n        if not state.is_world_process_zero or model is None:\r\n            return\r\n\r\n        metrics = {}\r\n\r\n        # Average L2 norm of trainable parameters\r\n        with torch.no_grad():\r\n            param_norm_sq = sum(\r\n                torch.norm(p).item() ** 2\r\n                for p in model.parameters()\r\n                if p.requires_grad\r\n            )\r\n            param_count = sum(\r\n                p.numel() for p in model.parameters() if p.requires_grad\r\n            )\r\n            if param_count > 0:\r\n                metrics[\"train/avg_param_norm\"] = (param_norm_sq / param_count) ** 0.5\r\n\r\n        # GPU memory\r\n        if torch.cuda.is_available():\r\n            metrics[\"train/gpu_memory_used_MB\"] = torch.cuda.memory_allocated() / 1024**2\r\n            metrics[\"train/gpu_memory_reserved_MB\"] = torch.cuda.memory_reserved() / 1024**2\r\n\r\n        if metrics:\r\n            wandb.log(metrics)\r\n","shared/paths.py":"\"\"\"\r\nPath helpers for experiment scripts.\r\n\r\nEach experiment script lives at:\r\n    <task>/experiments/<exp_name>/scripts/<script>.py\r\n\r\nThe helpers below derive standard paths relative to any script file,\r\nso scripts work correctly regardless of which directory you cd into.\r\n\r\nExample usage in a script:\r\n    import sys\r\n    from pathlib import Path\r\n    sys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\n    from shared.paths import experiment_dir, data_dir, config_dir\r\n\r\n    DATA   = data_dir(__file__)    # → <task>/experiments/<exp_name>/data/\r\n    CONFIG = config_dir(__file__)  # → <task>/experiments/<exp_name>/configs/\r\n    OUT    = output_dir(__file__)  # → <task>/experiments/<exp_name>/outputs/\r\n\"\"\"\r\n\r\nfrom pathlib import Path\r\n\r\n\r\ndef experiment_dir(script_file: str) -> Path:\r\n    \"\"\"Return the experiment directory (parent of the scripts/ folder).\"\"\"\r\n    return Path(script_file).resolve().parent.parent\r\n\r\n\r\ndef data_dir(script_file: str) -> Path:\r\n    \"\"\"Return the data directory for the current experiment.\"\"\"\r\n    return experiment_dir(script_file) / \"data\"\r\n\r\n\r\ndef output_dir(script_file: str) -> Path:\r\n    \"\"\"Return the outputs directory for the current experiment.\"\"\"\r\n    return experiment_dir(script_file) / \"outputs\"\r\n\r\n\r\ndef config_dir(script_file: str) -> Path:\r\n    \"\"\"Return the configs directory for the current experiment.\"\"\"\r\n    return experiment_dir(script_file) / \"configs\"\r\n\r\n\r\ndef codebase_root(script_file: str) -> Path:\r\n    \"\"\"\r\n    Return the calt-codebase-new root (4 levels above a script in\r\n    <task>/experiments/<exp>/scripts/).\r\n    \"\"\"\r\n    return Path(script_file).resolve().parents[4]\r\n","shared/plotting.py":"\"\"\"Plotting and inspection utilities for experiment analysis notebooks.\r\n\r\nIncludes a `showcase()` helper that mirrors `calt-codebase/examples/demos/utils.py`\r\n(the canonical helper used by the official `minimal_demo.ipynb`).\r\n\r\nFor raw access to the eval results, `load_eval_results` and `plot_success_rate`\r\ndelegate to `calt.io.visualization.comparison_vis.load_eval_results` — the\r\ncanonical loader for the eval JSON written by `evaluate_and_save_generation`.\r\n\r\nThe on-disk format is a JSON list of dicts:\r\n    [{\"generated\": \"...\", \"reference\": \"...\"}, ...]\r\n\"\"\"\r\n\r\nimport json\r\nimport os\r\nfrom pathlib import Path\r\n\r\nimport matplotlib.pyplot as plt\r\n\r\nfrom calt.io.visualization.comparison_vis import (\r\n    load_eval_results as _calt_load_eval_results,\r\n)\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Eval result loading\r\n# ---------------------------------------------------------------------------\r\n\r\ndef _resolve_eval_results_path(\r\n    results_dir: str | Path,\r\n    eval_results_path: str | None = None,\r\n) -> Path:\r\n    \"\"\"\r\n    Resolve the path to an eval results JSON.\r\n\r\n    Preference order:\r\n      1. Explicit `eval_results_path` if given.\r\n      2. ``<results_dir>/eval_results.json`` if present.\r\n      3. The most recent ``step_*.json`` inside ``<results_dir>/eval_results/``.\r\n\r\n    Raises FileNotFoundError with a helpful message otherwise.\r\n    \"\"\"\r\n    if eval_results_path is not None:\r\n        return Path(eval_results_path)\r\n\r\n    results_dir = Path(results_dir)\r\n    direct = results_dir / \"eval_results.json\"\r\n    if direct.is_file():\r\n        return direct\r\n\r\n    step_dir = results_dir / \"eval_results\"\r\n    if step_dir.is_dir():\r\n        steps = sorted(\r\n            step_dir.glob(\"step_*.json\"),\r\n            key=lambda p: int(p.stem.replace(\"step_\", \"\")),\r\n        )\r\n        if steps:\r\n            return steps[-1]\r\n\r\n    raise FileNotFoundError(\r\n        f\"No eval_results.json or eval_results/step_*.json under {results_dir}. \"\r\n        \"Run train.py first.\"\r\n    )\r\n\r\n\r\ndef load_eval_results(results_dir: str | Path) -> tuple[list[str], list[str]]:\r\n    \"\"\"\r\n    Load the latest evaluation results from a results directory.\r\n\r\n    Returns (generated_texts, reference_texts).\r\n    \"\"\"\r\n    path = _resolve_eval_results_path(results_dir)\r\n    return _calt_load_eval_results(str(path))\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# showcase: port of calt-codebase/examples/demos/utils.py::showcase\r\n# ---------------------------------------------------------------------------\r\n\r\ndef showcase(\r\n    dataset,\r\n    success_cases: bool = True,\r\n    num_show: int = 5,\r\n    eval_results_path: str | None = None,\r\n    results_dir: str = \"results\",\r\n) -> None:\r\n    \"\"\"\r\n    Print up to `num_show` success (or failure) cases from the latest eval results.\r\n\r\n    Direct port of `calt-codebase/examples/demos/utils.py::showcase` so notebook\r\n    output matches the official `minimal_demo.ipynb`.\r\n\r\n    Parameters\r\n    ----------\r\n    dataset\r\n        The test_dataset returned by `IOPipeline.build()`. Its `preprocessor`\r\n        is used to decode the tokenized strings stored in eval results.\r\n    success_cases : bool\r\n        True → print correct predictions. False → print mistakes.\r\n    num_show : int\r\n        Maximum number of cases to print.\r\n    eval_results_path : str | None\r\n        Explicit path to an eval JSON. If None, auto-resolved from `results_dir`.\r\n    results_dir : str\r\n        Output directory of the training run (default \"results\").\r\n    \"\"\"\r\n    if success_cases:\r\n        indicator_fn = lambda gen, ref: gen == ref  # noqa: E731\r\n        tag = \"success\"\r\n    else:\r\n        indicator_fn = lambda gen, ref: gen != ref  # noqa: E731\r\n        tag = \"failure\"\r\n\r\n    path = _resolve_eval_results_path(results_dir, eval_results_path)\r\n    gen_texts, ref_texts = _calt_load_eval_results(str(path))\r\n    cases = [\r\n        (i, gen, ref)\r\n        for i, (gen, ref) in enumerate(zip(gen_texts, ref_texts))\r\n        if indicator_fn(gen, ref)\r\n    ]\r\n\r\n    print(\"-------------------------\")\r\n    print(f\"\"\" {tag} cases ({len(cases)} total) \"\"\")\r\n    print(\"-------------------------\")\r\n    for i, gen, ref in cases[:num_show]:\r\n        gen_expr = dataset.preprocessor.decode(gen)\r\n        ref_expr = dataset.preprocessor.decode(ref)\r\n        print(f\"  [{i}] gen: {gen_expr}  |  ref: {ref_expr}\")\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# show_examples: print n success or failure cases from pre-loaded lists\r\n# ---------------------------------------------------------------------------\r\n\r\ndef show_examples(\r\n    generated: list[str],\r\n    references: list[str],\r\n    n: int = 5,\r\n    successes: bool = True,\r\n) -> None:\r\n    \"\"\"\r\n    Print up to `n` success (or failure) cases from pre-loaded result lists.\r\n\r\n    Parameters\r\n    ----------\r\n    generated : list[str]\r\n        Model predictions (as returned by load_eval_results).\r\n    references : list[str]\r\n        Ground-truth strings.\r\n    n : int\r\n        Maximum number of cases to print.\r\n    successes : bool\r\n        True → print correct predictions. False → print mistakes.\r\n    \"\"\"\r\n    tag = \"success\" if successes else \"failure\"\r\n    cases = [\r\n        (i, gen, ref)\r\n        for i, (gen, ref) in enumerate(zip(generated, references))\r\n        if (gen == ref) == successes\r\n    ]\r\n    print(\"-------------------------\")\r\n    print(f\" {tag} cases ({len(cases)} total) \")\r\n    print(\"-------------------------\")\r\n    for i, gen, ref in cases[:n]:\r\n        print(f\"  [{i}] predicted : {gen}\")\r\n        print(f\"       reference : {ref}\")\r\n\r\n\r\n# ---------------------------------------------------------------------------\r\n# Plotting\r\n# ---------------------------------------------------------------------------\r\n\r\ndef plot_success_rate(results_dir: str | Path, ax=None) -> plt.Axes:\r\n    \"\"\"\r\n    Plot exact-match success rate over training steps.\r\n\r\n    Reads all ``step_*.json`` files in ``<results_dir>/eval_results/`` and\r\n    plots success rate vs step.\r\n    \"\"\"\r\n    results_dir = Path(results_dir)\r\n    step_dir = results_dir / \"eval_results\"\r\n    if not step_dir.is_dir():\r\n        raise FileNotFoundError(f\"No eval_results/ directory in {results_dir}\")\r\n\r\n    steps, rates = [], []\r\n    for p in sorted(step_dir.glob(\"step_*.json\"), key=lambda p: int(p.stem.replace(\"step_\", \"\"))):\r\n        step = int(p.stem.replace(\"step_\", \"\"))\r\n        with open(p) as f:\r\n            data = json.load(f)\r\n        if not data:\r\n            continue\r\n        gen = [item.get(\"generated\", \"\") for item in data]\r\n        ref = [item.get(\"reference\", \"\") for item in data]\r\n        rate = sum(g == r for g, r in zip(gen, ref)) / len(ref)\r\n        steps.append(step)\r\n        rates.append(rate * 100)\r\n\r\n    if ax is None:\r\n        _, ax = plt.subplots(figsize=(8, 4))\r\n    ax.plot(steps, rates, marker=\"o\", linewidth=2)\r\n    ax.set_xlabel(\"Training step\")\r\n    ax.set_ylabel(\"Success rate (%)\")\r\n    ax.set_title(\"Exact-match success rate\")\r\n    ax.grid(True, alpha=0.3)\r\n    return ax\r\n","shared/preprocess.py":"\"\"\"\r\nRe-export shim for `calt.preprocess`.\r\n\r\nThe canonical implementation now lives in the CALT library\r\n(`/home/.../site-packages/calt/preprocess.py`) so that any project building on\r\nCALT can benefit from offline preprocessing without re-implementing it.\r\n\r\nThis file is kept only for backwards compatibility with the small number of\r\nimports that already write `from shared.preprocess import ...`. New code should\r\nimport from `calt.preprocess` directly.\r\n\r\nIf you ever `pip install --upgrade calt-x` and the `calt/preprocess.py` file\r\ndisappears from site-packages, restore it from this project's backup:\r\n\r\n    /data/t-maxime/backups/calt-sitepackages_before-preprocess_20260526.tar.gz\r\n\r\nor copy the previous version of this file (see git history) which contained\r\nthe full implementation inline.\r\n\"\"\"\r\n\r\nfrom calt.preprocess import (  # noqa: F401\r\n    PREPROCESS_VERSION,\r\n    compute_config_hash,\r\n    get_cache_dir,\r\n    maybe_use_processed_cache,\r\n    run_preprocess,\r\n)\r\n\r\n__all__ = [\r\n    \"PREPROCESS_VERSION\",\r\n    \"compute_config_hash\",\r\n    \"get_cache_dir\",\r\n    \"maybe_use_processed_cache\",\r\n    \"run_preprocess\",\r\n]\r\n","shared/README.md":"# shared/\r\n\r\nUtilities shared across all tasks. Import from here instead of duplicating code.\r\n\r\n| File | What it provides |\r\n|---|---|\r\n| `seed.py` | `set_seed(n)` — fix all random seeds (Python, NumPy, PyTorch, HuggingFace) |\r\n| `config.py` | `load_config(path, overrides)` — load YAML with optional CLI overrides |\r\n| `paths.py` | `data_dir(__file__)`, `config_dir(__file__)` — paths relative to the script |\r\n| `calt_adapter.py` | Re-exports `DatasetPipeline`, `IOPipeline`, `ModelPipeline`, `TrainerPipeline` |\r\n| `logging.py` | `CustomLoggingCallback` — logs gradient norms and GPU memory to wandb |\r\n| `plotting.py` | `plot_success_rate()`, `show_examples()` — for analysis notebooks |\r\n\r\n## Usage example\r\n\r\n```python\r\nimport sys\r\nfrom pathlib import Path\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[4]))\r\n\r\nfrom shared import set_seed, load_config\r\nfrom shared.paths import data_dir, config_dir\r\n\r\nset_seed(42)\r\ncfg = load_config(config_dir(__file__) / \"train.yaml\")\r\n```\r\n","shared/seed.py":"\"\"\"Fix all random seeds for fully reproducible experiments.\"\"\"\r\n\r\nimport os\r\nimport random\r\n\r\nimport numpy as np\r\nimport torch\r\nfrom transformers import set_seed as hf_set_seed\r\n\r\n\r\ndef set_seed(seed: int = 42) -> None:\r\n    \"\"\"\r\n    Fix random seeds for Python, NumPy, PyTorch, and HuggingFace.\r\n\r\n    Call this at the top of any training or generation script.\r\n\r\n    Parameters\r\n    ----------\r\n    seed : int\r\n        The seed value. Default is 42.\r\n    \"\"\"\r\n    os.environ[\"PYTHONHASHSEED\"] = str(seed)\r\n    random.seed(seed)\r\n    np.random.seed(seed)\r\n    torch.manual_seed(seed)\r\n    torch.cuda.manual_seed(seed)\r\n    torch.cuda.manual_seed_all(seed)\r\n    torch.backends.cudnn.benchmark = False\r\n    torch.backends.cudnn.deterministic = True\r\n    hf_set_seed(seed)\r\n    # Required env var for deterministic CuBLAS on CUDA >= 10.2\r\n    os.environ.setdefault(\"CUBLAS_WORKSPACE_CONFIG\", \":4096:8\")\r\n    torch.use_deterministic_algorithms(True)\r\n","shared/user_postprocessor.py":"\"\"\"\r\nUser-defined post-processing hooks (task 3).\r\n\r\nTwo optional slots, applied AFTER each task's load-time chain has produced\r\n`(input_text, target_text)`. Both are pure-Python functions the user can write.\r\n\r\n    1. Base hook   — file `shared/base_postprocessor.py`\r\n                     Applied to ALL tasks that wire postprocessing in their\r\n                     `build_load_preprocessor`.\r\n\r\n    2. Per-task hook — file `<task>/core/postprocessor.py`\r\n                       Applied only to that specific task, AFTER the base hook.\r\n\r\nEach hook must expose a function with the exact signature:\r\n\r\n    def postprocess(input_text: str, target_text: str) -> tuple[str, str]:\r\n        return input_text, target_text   # default: identity\r\n\r\nBoth files are OPT-IN: if the file does not exist, the corresponding hook is\r\nskipped and the chain stays exactly as it was before task 3 — no behavior\r\nchange, no cache invalidation.\r\n\r\nHash sensitivity\r\n----------------\r\nWhen a hook is wired, its source code is included in the preprocessing cache\r\nhash, so any edit to a hook function invalidates the cache (preventing stale\r\ndata from being reused with mismatched preprocessing).\r\n\r\nUsage from a task's `build_load_preprocessor`\r\n---------------------------------------------\r\n    from shared.user_postprocessor import (\r\n        get_user_postprocessors,\r\n        UserPostProcessorAdapter,\r\n        RawLineToTupleAdapter,\r\n    )\r\n\r\n    funcs = get_user_postprocessors(task_pkg=\"groebner_basis\")\r\n    if funcs:\r\n        # If task's own chain is empty, ensure we parse raw line first\r\n        if not chain:\r\n            chain.append(RawLineToTupleAdapter())\r\n        chain.append(UserPostProcessorAdapter(funcs))\r\n\"\"\"\r\n\r\nfrom __future__ import annotations\r\n\r\nimport hashlib\r\nimport importlib\r\nimport inspect\r\nimport linecache\r\nfrom pathlib import Path\r\nfrom typing import Callable\r\n\r\nPostFn = Callable[[str, str], tuple[str, str]]\r\n\r\n\r\n# --------------------------------------------------------------------------- #\r\n# Hook loading                                                                 #\r\n# --------------------------------------------------------------------------- #\r\n\r\ndef _try_import_postprocess(module_name: str) -> PostFn | None:\r\n    \"\"\"Import `<module_name>.postprocess` if it exists; return None otherwise.\"\"\"\r\n    try:\r\n        mod = importlib.import_module(module_name)\r\n    except ModuleNotFoundError:\r\n        return None\r\n    fn = getattr(mod, \"postprocess\", None)\r\n    if fn is None or not callable(fn):\r\n        return None\r\n    return fn\r\n\r\n\r\ndef get_user_postprocessors(task_pkg: str) -> list[PostFn]:\r\n    \"\"\"\r\n    Return the list of postprocess hooks to apply, in execution order.\r\n\r\n    Order: [base, task_specific]. Empty list if neither file exists.\r\n\r\n    Parameters\r\n    ----------\r\n    task_pkg : str\r\n        The Python package name of the task (e.g. \"groebner_basis\").\r\n        Looks for `<task_pkg>.core.postprocessor.postprocess`.\r\n    \"\"\"\r\n    hooks: list[PostFn] = []\r\n    base = _try_import_postprocess(\"shared.base_postprocessor\")\r\n    if base is not None:\r\n        hooks.append(base)\r\n    task = _try_import_postprocess(f\"{task_pkg}.core.postprocessor\")\r\n    if task is not None:\r\n        hooks.append(task)\r\n    return hooks\r\n\r\n\r\n# --------------------------------------------------------------------------- #\r\n# Cache-hash contribution                                                      #\r\n# --------------------------------------------------------------------------- #\r\n\r\ndef user_postprocessor_hash_contribution(task_pkg: str) -> bytes:\r\n    \"\"\"\r\n    Return the bytes that should be folded into the preprocessing cache hash.\r\n\r\n    For each hook present, includes the FULL source of its module. This way\r\n    edits to a hook function invalidate the cache; absent hooks contribute\r\n    empty bytes (no behavior change for users who never write a hook).\r\n    \"\"\"\r\n    h = hashlib.sha256()\r\n    for module_name in (\"shared.base_postprocessor\", f\"{task_pkg}.core.postprocessor\"):\r\n        try:\r\n            mod = importlib.import_module(module_name)\r\n            # Invalidate linecache for this file so inspect.getsource picks up\r\n            # post-edit content rather than returning a stale cached source.\r\n            src_file = inspect.getsourcefile(mod)\r\n            if src_file:\r\n                linecache.checkcache(src_file)\r\n            src = inspect.getsource(mod)\r\n            h.update(module_name.encode())\r\n            h.update(b\"\\x00\")\r\n            h.update(src.encode())\r\n            h.update(b\"\\x00\")\r\n        except (ModuleNotFoundError, OSError, TypeError):\r\n            # Module absent OR source unavailable → contribute nothing for this slot\r\n            continue\r\n    return h.digest()\r\n\r\n\r\n# --------------------------------------------------------------------------- #\r\n# Adapters that plug into CALT's ChainLoadPreprocessor                         #\r\n# --------------------------------------------------------------------------- #\r\n\r\nclass RawLineToTupleAdapter:\r\n    \"\"\"\r\n    Splits a raw `\"input # target\"` line into `(input, target)`.\r\n\r\n    Used as the FIRST step of the chain when a task has no other load\r\n    preprocessor (e.g. groebner degrevlex+raw) but the user wired hooks.\r\n    CALT's chain expects the first preprocessor to handle the raw source.\r\n\r\n    Same parsing as `calt.io.read.read_data_from_file` (single `#` split).\r\n    \"\"\"\r\n\r\n    def process_sample(self, source):\r\n        if isinstance(source, str):\r\n            line = source.strip()\r\n            if \"#\" not in line:\r\n                raise ValueError(\r\n                    f\"Raw line must contain '#' separating input and target: {line[:80]!r}...\"\r\n                )\r\n            input_part, target_part = line.split(\"#\", 1)\r\n            return input_part.strip(), target_part.strip()\r\n        # Already a tuple/dict from an earlier preprocessor — pass through unchanged.\r\n        return source\r\n\r\n\r\nclass UserPostProcessorAdapter:\r\n    \"\"\"\r\n    Wraps user hooks into a CALT-compatible LoadPreprocessor.\r\n\r\n    Receives `(input_text, target_text)` from the previous step, applies each\r\n    user function in order, returns `(input_text, target_text)`.\r\n    \"\"\"\r\n\r\n    def __init__(self, hooks: list[PostFn]):\r\n        if not hooks:\r\n            raise ValueError(\"UserPostProcessorAdapter requires at least one hook\")\r\n        self.hooks = list(hooks)\r\n\r\n    def process_sample(self, source):\r\n        if isinstance(source, tuple) and len(source) == 2:\r\n            inp, tgt = source\r\n        elif isinstance(source, dict):\r\n            # Should be unusual at this stage; convert to tuple for hooks.\r\n            inp = source.get(\"problem\")\r\n            tgt = source.get(\"answer\", source.get(\"solution\"))\r\n        else:\r\n            raise TypeError(\r\n                f\"UserPostProcessorAdapter expects (str, str) tuple or dict, got {type(source).__name__}\"\r\n            )\r\n        for fn in self.hooks:\r\n            inp, tgt = fn(inp, tgt)\r\n        return inp, tgt\r\n\r\n\r\n__all__ = [\r\n    \"PostFn\",\r\n    \"get_user_postprocessors\",\r\n    \"user_postprocessor_hash_contribution\",\r\n    \"RawLineToTupleAdapter\",\r\n    \"UserPostProcessorAdapter\",\r\n]\r\n","shared/__init__.py":"from .seed import set_seed\r\nfrom .config import load_config\r\nfrom .paths import experiment_dir, data_dir, output_dir, config_dir\r\nfrom .plotting import showcase, load_eval_results, plot_success_rate\r\n\r\n__all__ = [\r\n    \"set_seed\",\r\n    \"load_config\",\r\n    \"experiment_dir\",\r\n    \"data_dir\",\r\n    \"output_dir\",\r\n    \"config_dir\",\r\n    \"showcase\",\r\n    \"load_eval_results\",\r\n    \"plot_success_rate\",\r\n]\r\n","pyproject.toml":"[project]\nname = \"calt-experiments\"\nversion = \"0.1.0\"\ndescription = \"Experiments for learning algebraic computations with Transformers\"\nrequires-python = \">=3.10,<3.13\"\ndependencies = [\n    \"calt-x==1.1.0\",  # pinned; see requirements.txt for the upgrade steps\n    \"omegaconf>=2.3.0\",\n    \"matplotlib>=3.7.0\",\n    \"click>=8.0.0\",\n]\n\n[tool.ruff]\nline-length = 100\n","requirements.txt":"# Python dependencies for running a downloaded CALT project.\n# Install everything in one step with:\n#   bash install.sh        (Linux / macOS / WSL)\n#   ./install.ps1          (Windows PowerShell)\n# calt-x is pinned to the version the bundled task files were tested against.\n# To upgrade: bump this line, then re-bundle the site (npm run sync:tasks), and test a task.\ncalt-x==1.1.0\nomegaconf\nmatplotlib\nclick\nsympy\n# wandb is pulled in by calt-x; the builder un-comments this only as a reminder\n# when a task turns progress logging on. You still need a free account + \"wandb login\".\n# wandb\n","install.sh":"#!/usr/bin/env bash\n# One-step setup for this CALT project.\n# Creates a local virtual environment (.venv) and installs the dependencies.\n# For the polynomial tasks (groebner_basis, border_basis) it can also help set\n# up SageMath through conda.\nset -e\n\ncd \"$(dirname \"$0\")\"\n\n# 1. Find a usable Python. calt-x needs 3.10, 3.11, or 3.12.\nPY=python3\ncommand -v \"$PY\" >/dev/null 2>&1 || PY=python\nif ! command -v \"$PY\" >/dev/null 2>&1; then\n  echo \"ERROR: Python was not found.\"\n  echo \"       Install Python 3.10, 3.11, or 3.12 first: https://www.python.org/downloads/\"\n  exit 1\nfi\n\nPYVER=$(\"$PY\" -c 'import sys; print(\"%d.%d\" % sys.version_info[:2])')\nif ! \"$PY\" -c 'import sys; raise SystemExit(0 if (3, 10) <= sys.version_info[:2] < (3, 13) else 1)'; then\n  echo \"ERROR: CALT needs Python 3.10, 3.11, or 3.12, but found $PYVER.\"\n  echo \"       Install a supported version and run this script again.\"\n  exit 1\nfi\necho \"==> Using Python $PYVER\"\n\n# 2. Create the virtual environment and install the pip dependencies.\necho \"==> Creating a virtual environment in .venv\"\n\"$PY\" -m venv .venv\n\n# shellcheck disable=SC1091\nsource .venv/bin/activate\n\necho \"==> Upgrading pip\"\npython -m pip install --upgrade pip\n\necho \"==> Installing dependencies from requirements.txt\"\npip install -r requirements.txt\n\necho \"\"\necho \"All set. The 'parity' task is ready to run.\"\necho \"Next time, activate the environment with:  source .venv/bin/activate\"\n\n# 3. SageMath is only needed for the polynomial tasks (groebner_basis, border_basis).\necho \"\"\nif command -v sage >/dev/null 2>&1; then\n  echo \"==> SageMath detected. The polynomial tasks (groebner_basis, border_basis) will work.\"\nelse\n  echo \"Note: the polynomial tasks (groebner_basis, border_basis) need SageMath.\"\n  echo \"      pip cannot install it; the easiest way is a conda environment.\"\n  if command -v conda >/dev/null 2>&1; then\n    printf \"      Create a conda env 'calt' with SageMath now? It is a large download. [y/N] \"\n    read -r reply\n    case \"$reply\" in\n      [Yy]*)\n        echo \"==> Creating conda env 'calt' with SageMath (this can take a while)...\"\n        conda create -y -n calt -c conda-forge sage \"python=3.11\"\n        echo \"==> Installing requirements into the 'calt' env\"\n        conda run -n calt pip install -r requirements.txt\n        echo \"\"\n        echo \"Done. For the polynomial tasks, use that env:  conda activate calt\"\n        ;;\n      *)\n        echo \"      Skipped. When you are ready, run:\"\n        echo \"          conda create -n calt -c conda-forge sage python=3.11\"\n        echo \"          conda activate calt\"\n        echo \"          pip install -r requirements.txt\"\n        ;;\n    esac\n  else\n    echo \"      Install conda first (Miniforge: https://github.com/conda-forge/miniforge), then:\"\n    echo \"          conda create -n calt -c conda-forge sage python=3.11\"\n    echo \"          conda activate calt\"\n    echo \"          pip install -r requirements.txt\"\n  fi\nfi\n","install.ps1":"# One-step setup for this CALT project (Windows PowerShell).\n# Creates a local virtual environment (.venv) and installs the dependencies.\n$ErrorActionPreference = \"Stop\"\nSet-Location -Path $PSScriptRoot\n\n# 1. Find a usable Python. calt-x needs 3.10, 3.11, or 3.12.\nif (-not (Get-Command python -ErrorAction SilentlyContinue)) {\n  Write-Host \"ERROR: Python was not found.\"\n  Write-Host \"       Install Python 3.10, 3.11, or 3.12 first: https://www.python.org/downloads/\"\n  exit 1\n}\n\n$pyver = (python -c \"import sys; print('%d.%d' % sys.version_info[:2])\")\n$ok = (python -c \"import sys; print(1 if (3, 10) <= sys.version_info[:2] < (3, 13) else 0)\")\nif ($ok -ne \"1\") {\n  Write-Host \"ERROR: CALT needs Python 3.10, 3.11, or 3.12, but found $pyver.\"\n  Write-Host \"       Install a supported version and run this script again.\"\n  exit 1\n}\nWrite-Host \"==> Using Python $pyver\"\n\n# 2. Create the virtual environment and install the pip dependencies.\nWrite-Host \"==> Creating a virtual environment in .venv\"\npython -m venv .venv\n\nWrite-Host \"==> Activating the environment\"\n& .\\.venv\\Scripts\\Activate.ps1\n\nWrite-Host \"==> Upgrading pip\"\npython -m pip install --upgrade pip\n\nWrite-Host \"==> Installing dependencies from requirements.txt\"\npip install -r requirements.txt\n\nWrite-Host \"\"\nWrite-Host \"All set. The 'parity' task is ready to run.\"\nWrite-Host \"Next time, activate the environment with:  .\\.venv\\Scripts\\Activate.ps1\"\n\n# 3. SageMath is only needed for the polynomial tasks (groebner_basis, border_basis).\nWrite-Host \"\"\nif (Get-Command sage -ErrorAction SilentlyContinue) {\n  Write-Host \"==> SageMath detected. The polynomial tasks (groebner_basis, border_basis) will work.\"\n} else {\n  Write-Host \"Note: the polynomial tasks (groebner_basis, border_basis) need SageMath.\"\n  Write-Host \"      SageMath does not run natively on Windows and pip cannot install it.\"\n  Write-Host \"      Use WSL (Windows Subsystem for Linux) with conda:\"\n  Write-Host \"          wsl --install                 # once, then reopen in Ubuntu\"\n  Write-Host \"          conda create -n calt -c conda-forge sage python=3.11\"\n  Write-Host \"          conda activate calt\"\n  Write-Host \"          pip install -r requirements.txt\"\n  Write-Host \"\"\n  Write-Host \"      The 'parity' task works on Windows without any of this.\"\n}\n","CALT_SNAPSHOT.txt":"CALT project snapshot\n=====================\nBundled on : 2026-05-27\nEngine     : calt-x==1.1.0\n\nThese task files were captured by the CALT Task Builder on the date above.\nIf a task stops working after a calt-x release, check that the installed\ncalt-x matches the engine version listed here.\n"};
